/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D = globalThis.RA.D;
const Q=(w,n,s,p,o,k,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:o,answer:o[k],explain:x});
const C=(w,s,d,en,zh,st,g,r)=>({senseId:`${w}.s${s}`,domain:d,en,zh,structure:st,grammar:g,rationale:r,sourceType:'authored'});
const M=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[C(w,...c)],mistakes:[M(...m)],quiz:qs.map((q,i)=>Q(w,i+1,q[0],q[1],q[2],q[3],q[4]))});
P('esophagus','来自希腊语 oisophagos“食管”，经拉丁语与英语医学传统传入。',[1,'医学','After the surgeon removed the obstruction, the patient could swallow again as food passed through the esophagus from the throat toward the stomach.','外科医生取出梗阻后，患者恢复吞咽；食物可从咽部经食管进入胃。','After the surgeon removed the obstruction, the patient could swallow again / as food passed through the esophagus / from the throat toward the stomach.','解剖名词；美式常写 esophagus，英式常写 oesophagus。','食物从咽部通向胃所经过的肌肉管是食管。'],['The endoscope entered the esophagus, the tube that carries air from the throat to the lungs.','The endoscope entered the trachea, the tube that carries air from the throat to the lungs.','通向肺部输送空气的是气管 trachea；食管输送食物。'],[[1,'Which organ carries swallowed food from the throat toward the stomach?',['esophagus','windpipe','ureter'],0,'食管连接咽部与胃，输送食物。'],[1,'A doctor examining the esophagus is examining the?',['food-carrying tube behind the windpipe','air sacs inside the lungs','valve that pumps blood'],0,'esophagus 是消化道的一段，不是肺或心脏结构。'],[1,'Choose the medically accurate statement.',['Food travels down the esophagus.','Air normally travels down the esophagus to the lungs.','The esophagus filters blood in the kidneys.'],0,'食物经食管到胃；气体经气管到肺。'],[1,'The British spelling equivalent of esophagus is?',['oesophagus','oesophagous','esophagous'],0,'英式拼法通常在开头加 o，写作 oesophagus。']]);
P('esoteric','源于希腊语 esōterikos“内在的、圈内的”，指只有少数专门人士理解的。',[1,'科学史','The manuscript used esoteric notation understood only by a few specialists, so the curator added a plain-language guide for visitors.','手稿使用只有少数专家才懂的深奥符号，因此策展人给参观者补充了通俗指南。','The manuscript used esoteric notation / understood only by a few specialists / so the curator added a plain-language guide for visitors.','常修饰知识、术语、兴趣或仪式；重点是受众范围窄，不只是复杂。','只有少数专家读得懂的符号体现其圈内、深奥性质。'],['The esoteric safety sign was instantly understood by every first-time visitor without any specialist knowledge.','The universal safety sign was instantly understood by every first-time visitor without any specialist knowledge.','人人都能直接理解的标志是通用的，不是只有少数人懂的 esoteric。'],[[1,'An esoteric formula is most likely understood by?',['a small group with specialised knowledge','every passer-by at first glance','no living person under any circumstances'],0,'esoteric 强调只有少数具专门知识的人能够理解。'],[1,'Which topic might be called esoteric?',['a rare notation used within a narrow branch of physics','the posted hours of a public library','a universally recognised stop sign'],0,'小领域内的专门符号符合“圈内、深奥”。'],[1,'Calling a hobby esoteric suggests that it is?',['little known outside a specialised circle','required of every citizen','impossible to practise'],0,'该词说明受众有限，并不意味着事情不可能做。'],[1,'Choose the natural collocation.',['esoteric knowledge','esoteric yesterday','esoteric more quickly'],0,'esoteric 可修饰 knowledge 等名词。']]);
P('espouse','由古法语 espouser“娶、承诺”进入英语，现常表示公开支持一项事业、理论或政策。',[1,'公共政策','The mayor chose to espouse the proposal only after its cost estimates and effects on low-income residents had been made public.','市长在成本估算及其对低收入居民的影响公开后，才决定支持这项提案。','The mayor chose to espouse the proposal / only after its cost estimates and effects / on low-income residents had been made public.','正式及物动词，后接观点、原则、事业或政策；不是简单“提出”。','市长表明支持提案，符合 espouse 的现代常用义。'],['The candidate espoused the policy by rejecting it at every rally and urging voters to oppose it.','The candidate opposed the policy by rejecting it at every rally and urging voters to oppose it.','公开拒绝并号召反对表示 oppose，而不是 espouse。'],[[1,'To espouse a reform is to?',['publicly support it','quietly postpone it','measure its length'],0,'espouse 表示支持或倡导一项事业、主张。'],[1,'Which can naturally follow “espouse”?',['a principle','from a principle','at a principle'],0,'espouse 是及物动词，直接接所支持的原则。'],[1,'A group that espouses conservation is likely to?',['advocate protecting nature','campaign to destroy habitats','avoid stating any position'],0,'支持保护自然即倡导 conservation。'],[1,'Choose the closest meaning in “She espouses equal access.”',['She supports equal access.','She conceals equal access.','She calculates equal access.'],0,'此处 espouses 表示主张、支持。']]);
P('essentially','essential 加副词后缀 -ly；essential 经中古法语源自拉丁语 essentialis“本质的”。',[2,'概述','The two proposals look different in presentation, but they are essentially the same plan: both move the clinic to the station and extend evening hours.','两份提案的呈现方式不同，但本质上是同一计划：都把诊所迁到车站并延长晚间服务。','The two proposals look different in presentation, / but they are essentially the same plan: / both move the clinic to the station and extend evening hours.','句中表示“说到底、基本上”；也可修饰本质层面的特征。','后文概括两份提案的共同核心，体现 s2。'],['The plans were essentially identical, meaning they differed in every central feature.','The plans were fundamentally different, meaning they differed in every central feature.','中心特征全异不能称 essentially identical；改为 fundamentally different 才一致。'],[[1,'“Essentially, the room is a small laboratory” means?',['In its basic nature, the room is a small laboratory.','The room is located at the east entrance.','The room is made from a chemical called essence.'],0,'essentially s1 可表示就基本性质而言。'],[2,'A speaker says, “Essentially, we need more time.” The speaker is giving?',['the simple core of a complicated point','a list of every minor detail','a denial that time exists'],0,'essentially s2 用于提炼复杂情况的要点。'],[2,'Choose the closest paraphrase: “The two jobs are essentially alike.”',['The two jobs are basically alike.','The two jobs are exactly one minute long.','The two jobs have no relation at all.'],0,'此处 essentially 表示基本上。'],[1,'Which sentence uses essentially to describe basic nature?',['The device is essentially a pressure sensor.','The device was delivered on Tuesday.','The device is painted essentially blue.'],0,'“本质上是一种压力传感器”描述其核心性质。']]);
P('esthetical','由 aesthetic 的变体 esthetic 加 -al 构成，源头是希腊语 aisthētikos“感知的”；表示审美或美学的。',[1,'建筑设计','The committee considered esthetical qualities such as proportion and light, but it also required the building to meet accessibility rules.','委员会考虑比例、采光等审美品质，同时要求建筑符合无障碍规定。','The committee considered esthetical qualities / such as proportion and light, / but it also required the building to meet accessibility rules.','形容词；aesthetic 更常见，esthetical 是较少见的变体形式。','比例和光线属于视觉审美考量。'],['The esthetical review measured only the bridge’s load capacity and ignored its appearance entirely.','The structural review measured only the bridge’s load capacity and ignored its appearance entirely.','承载力属于结构性能而非审美；结构审查才吻合。'],[[1,'An esthetical judgment concerns?',['how something looks or is experienced as beautiful','how much electricity it consumes','whether it is legally owned'],0,'esthetical 指审美或美学方面。'],[1,'Which issue is most clearly esthetical?',['the balance of colour and shape in a poster','the bridge’s maximum weight limit','the date a permit expires'],0,'颜色与形状的视觉平衡属于审美问题。'],[1,'The more usual spelling related to esthetical is?',['aesthetic','athletic','ethical'],0,'aesthetic 是更常见的对应拼法。'],[1,'Choose the natural phrase.',['esthetical qualities of the room','esthetical arrived late','esthetical more slowly'],0,'形容词可修饰 qualities。']]);
P('estimable','estimate 源于拉丁语 aestimare“评估、重视”，estimable 加 -able 可表示值得尊敬或可以估算。',[1,'人物评价','Although she held no senior title, colleagues found her estimable because she admitted uncertainty and gave credit to junior researchers.','她虽没有高级头衔，同事仍认为她值得尊敬，因为她坦承不确定之处并肯定初级研究者的贡献。','Although she held no senior title, / colleagues found her estimable / because she admitted uncertainty and gave credit to junior researchers.','本句为“值得尊敬的”义；另有较少用的“可估计的”义。','坦诚并尊重他人的品质支持 s1 的评价。'],['The estimable referee cheated both teams and concealed the match results.','The disreputable referee cheated both teams and concealed the match results.','作弊和隐瞒败坏声誉，适合 disreputable 而非值得尊敬的 estimable。'],[[1,'An estimable colleague is one who is?',['worthy of respect','impossible to assess','always wealthy'],0,'estimable s1 指值得尊敬的。'],[2,'If a quantity is estimable, it is?',['capable of being assessed or calculated','certainly not measurable','worthy of receiving a medal'],0,'estimable s2 表示可以估算。'],[1,'Which behaviour could make a person estimable?',['taking responsibility for an honest mistake','taking credit for another person’s work','hiding evidence from the team'],0,'诚实负责的品质使人值得尊敬。'],[2,'Choose the correct interpretation: “The damage is estimable from the survey.”',['The damage can be estimated using the survey.','The damage deserves admiration.','The survey has no measurable results.'],0,'此句采用“可估计”义。']]);
P('estivation','经拉丁语 aestivatio/aestivare“度夏”形成，指动物在高温或干旱时期进入的休眠状态。',[1,'动物生理','During the dry season, the land snail sealed its shell opening and entered estivation, remaining inactive until moisture returned.','旱季里，陆生蜗牛封住壳口并进入夏眠，直到水分恢复才重新活动。','During the dry season, the land snail sealed its shell opening / and entered estivation, / remaining inactive until moisture returned.','生物学术语，常与 drought、heat、summer 语境相关；英式也拼 aestivation。','蜗牛在干旱中停滞活动，符合 estivation。'],['The field guide called the snail’s winter migration to a warmer forest estivation.','The field guide called the snail’s heat- or drought-season dormancy estivation.','迁往暖处不是该术语；estivation 指炎热或干旱期间的休眠。'],[[1,'Estivation helps an animal survive?',['hot or dry conditions by becoming inactive','a sudden shortage of oxygen while swimming','the coldest part of winter only'],0,'estivation 是高温或干旱季节的休眠。'],[1,'Which animal behaviour is estivation?',['a snail sealing its shell during drought','a bird flying south for winter','a fish laying eggs in spring'],0,'蜗牛在干旱中封壳休眠是夏眠。'],[1,'The British spelling variant is?',['aestivation','estivatione','estivication'],0,'英式拼法常在词首保留 ae。'],[1,'During estivation, metabolism is generally?',['lowered as activity declines','accelerated by constant feeding','unrelated to the animal’s condition'],0,'夏眠伴随活动及代谢降低。']]);
P('estrange','源自古法语 estranger“使陌生”，最终关联拉丁语 extraneus“外来的”，现指使关系疏远。',[1,'家庭关系','Years of unanswered letters had estranged the sisters, so their aunt arranged a quiet meeting without asking either to make an immediate apology.','多年没有回信使姐妹俩渐渐疏远，因此姑妈安排了一次平静会面，没有要求任何一方立刻道歉。','Years of unanswered letters had estranged the sisters, / so their aunt arranged a quiet meeting / without asking either to make an immediate apology.','及物动词；常用 estrange A from B，描述关系疏离。','未回应的信件导致姐妹关系疏远，体现该词。'],['The shared project estranged the neighbors by bringing them closer and restoring their trust.','The shared project reconciled the neighbors by bringing them closer and restoring their trust.','恢复信任、拉近关系是 reconciled，与使人疏远的 estrange 相反。'],[[1,'To estrange two friends is to?',['cause them to become distant from each other','help them settle every disagreement','introduce them for the first time'],0,'estrange 表示使关系疏远。'],[1,'Choose the correct pattern.',['estrange a child from a parent','estrange a child with a parent','estrange from a child a parent'],0,'常见结构是 estrange someone from someone。'],[1,'Which event might estrange siblings?',['a long conflict that destroys their trust','a thoughtful conversation that repairs trust','a shared celebration that brings them together'],0,'长期破坏信任的冲突可能使手足疏远。'],[1,'“The dispute estranged him from his friends” means it?',['made him less close to them','made him their employer','taught him their names'],0,'estranged from 表示与某人关系变远。']]);
P('estuarine','由 estuary 加形容词后缀 -ine；estuary 经拉丁语 aestuarium“潮汐水域”进入英语。',[1,'生态学','The estuarine marsh supports young fish because fresh river water mixes with seawater and supplies sheltered feeding grounds.','河口沼泽为幼鱼提供栖息地，因为河水与海水在此混合，并形成受保护的觅食区。','The estuarine marsh supports young fish / because fresh river water mixes with seawater / and supplies sheltered feeding grounds.','形容词，修饰 marsh、species、sediment 等与河口有关的名词。','淡水与海水交汇、受潮汐影响的湿地是 estuarine 环境。'],['The estuarine field station stood far inland beside a freshwater spring with no tidal influence.','The alpine field station stood far inland beside a freshwater spring with no tidal influence.','远离海岸且没有潮汐影响的地点不是河口环境；alpine 更合适。'],[[1,'An estuarine habitat is found?',['where a river meets the sea and tides affect the water','on a dry mountain summit','inside a freshwater glacier'],0,'estuarine 指河口及受潮汐影响的环境。'],[1,'Which study is estuarine research?',['measuring salt levels where river and sea water mix','tracking snow on a high plateau','mapping caves far inland'],0,'河海混合水域的盐度测量属于河口研究。'],[1,'Choose the natural collocation.',['estuarine ecosystem','estuarine yesterday','estuarine very carefully'],0,'estuarine 是修饰 ecosystem 的形容词。'],[1,'Estuarine water is typically influenced by?',['both river flow and tides','only desert wind','volcanic ash alone'],0,'河口水体兼受河流与潮汐作用。']]);
P('estuary','源自拉丁语 aestuarium“潮水涨落之处”，指河流受潮汐影响、入海前扩宽的下游河段。',[1,'地理','At the estuary, the river widened into tidal channels, and the salinity changed as seawater moved inland with each high tide.','河口处河流扩展成潮汐水道；每次涨潮时海水向内陆推进，盐度随之变化。','At the estuary, the river widened into tidal channels, / and the salinity changed / as seawater moved inland with each high tide.','可数名词；常与 river、tidal、coastal 连用，区别于单纯河岸或海湾。','河流入海并受潮汐影响的宽阔河段即河口。'],['The map marked the dry source of the river on a mountain as its estuary.','The map marked the tidal mouth where the river widens into the sea as its estuary.','河流源头不受海潮影响；estuary 指河流下游入海的潮汐河口。'],[[1,'An estuary is the part of a river?',['near its mouth where tides may move seawater inland','where it first begins as a mountain spring','that is entirely underground'],0,'河口位于河流入海处并常受潮汐影响。'],[1,'Which observation supports calling a place an estuary?',['river water mixes with tidal seawater','the water is frozen year-round','the river has no connection to the coast'],0,'淡水、海水混合及潮汐作用是河口特征。'],[1,'Choose the natural phrase.',['the river estuary','the estuary of a mountain peak','an estuary of pure desert sand'],0,'河口属于河流的下游入海区域。'],[1,'An estuary differs from a river source because it lies?',['at the lower, tidal end of the river','at the river’s highest inland beginning','above the clouds'],0,'源头在内陆上游，河口在下游入海处。']]);
P('etch','经荷兰语 etsen“用酸腐蚀”进入英语，现指以酸蚀刻线条，也可泛指刻画、铭记。',[1,'版画制作','The artist coated a copper plate with wax, drew the design through it, and used acid to etch fine lines into the exposed metal.','艺术家先给铜版涂蜡，再划开图案处的蜡层，随后用酸在裸露金属上蚀刻细线。','The artist coated a copper plate with wax, / drew the design through it, / and used acid to etch fine lines into the exposed metal.','及物动词；常用 etch a design/name into/on a surface。','酸在金属表面刻出图线，是 etch 的制作义。'],['The printmaker etched the copper plate by painting a design on paper without touching the metal.','The printmaker sketched the design on paper without touching the metal.','没有在金属上蚀刻，只是在纸上画草图，应为 sketch。'],[[1,'To etch a design into metal is to?',['cut or corrode lines into its surface','cover it with a loose sheet of paper','weigh it on a scale'],0,'etch 指在硬表面上刻出线条。'],[1,'Which tool is especially associated with traditional etching?',['acid acting on an exposed plate','a kettle used to boil tea','a ruler used only to measure cloth'],0,'传统蚀刻可利用酸腐蚀暴露的金属。'],[1,'Choose the correct construction.',['etch a name into glass','etch a name from loudly','etch into a name glass'],0,'常说 etch a name into a surface。'],[1,'“The landscape was etched in her memory” uses etch?',['figuratively, meaning fixed clearly in memory','as a term for boiling liquid','to mean erase completely'],0,'比喻用法表示深刻铭记。']]);
P('ether','经拉丁语与新拉丁化学命名进入英语；ether 的古典词源为希腊语 aithēr“高空清气”，化学上指一类挥发性液体。',[1,'化学史','The museum label notes that ether was once used as an anaesthetic, although modern operating rooms rely on safer and more controllable agents.','博物馆说明乙醚曾用作麻醉剂，不过现代手术室依赖更安全、易控制的药剂。','The museum label notes that ether was once used as an anaesthetic, / although modern operating rooms rely / on safer and more controllable agents.','化学名词；在本词条中特指乙醚，历史用途不代表现代医疗建议。','展签讲的是旧时用作麻醉剂的挥发性化合物。'],['The chemistry label identified ether as a nonvolatile solid that cannot evaporate.','The chemistry label identified ether as a volatile liquid that can evaporate readily.','ether 在此为易挥发液体；“不挥发固体”与其性质相反。'],[[1,'In the chemistry sense, ether is?',['a volatile liquid compound','a permanent metal alloy','a kind of flowering tree'],0,'词条中的 ether 是挥发性化合物。'],[1,'The historical label says ether was formerly used as?',['an anaesthetic','a building material','a source of tree seeds'],0,'旧时乙醚曾用于麻醉。'],[1,'The ancient Greek source associated with the name ether meant?',['the upper air or clear sky','a river mouth','a written biography'],0,'古典词源指高空或清气。'],[1,'Which statement is accurate about this entry?',['Ether is a chemical term and a volatile liquid.','Ether is the name of a tidal river mouth.','Ether means a speech praising the dead.'],0,'該词条讲化学物质 ether，不是 estuary 或 eulogy。']]);
P('ethereal','来自希腊语 aithēr“高空清气”，经拉丁语 ethereus 进入英语；可指轻盈飘渺或仿佛天界的。',[1,'音乐','A single flute line gave the opening of the piece an ethereal quality, seeming to float above the measured pulse of the strings.','一条长笛旋律让乐曲开头显得轻盈飘渺，仿佛浮在弦乐稳定节拍之上。','A single flute line gave the opening of the piece an ethereal quality, / seeming to float above / the measured pulse of the strings.','ethereal s1 描述极轻柔、近乎不真实的质感；也可指天上的、非尘世的。','仿佛漂浮的轻柔旋律体现 s1。'],['The ethereal stone bridge felt heavy, solid, and completely ordinary, with no delicate or otherworldly quality.','The massive stone bridge felt heavy, solid, and completely ordinary, with no delicate or otherworldly quality.','沉重普通与 ethereal 的轻盈飘渺义相反；massive 合乎句意。'],[[1,'An ethereal melody is likely to sound?',['delicate and almost weightless','loudly mechanical and harsh','exactly like a spoken timetable'],0,'ethereal s1 可形容轻柔、飘渺的声音。'],[2,'In a spiritual description, an ethereal being seems?',['to belong to heaven rather than ordinary earthly life','to be made of heavy iron','to be an estuary animal'],0,'ethereal s2 指仿佛来自天界、非尘世的。'],[1,'Which image is most ethereal?',['misty light drifting through a quiet chapel','a concrete block on a weighing scale','a muddy boot beside a drain'],0,'朦胧、轻柔、似乎不真实的景象具 ethereal 质感。'],[1,'Choose the closest sense in “an ethereal voice.”',['a very light, delicate voice','a voice that gives a legal verdict','a voice that calculates a tax'],0,'此处取轻柔飘渺义。']]);
P('ethically','由 ethic 加副词后缀 -ally 构成；ethic 源自希腊语 ēthikos“道德、品格方面的”。',[1,'研究规范','The team asked whether the consent form was ethically adequate, since several participants could not read the language in which it was written.','团队询问该同意书在伦理上是否充分，因为有几名参与者看不懂文件所用语言。','The team asked whether the consent form was ethically adequate, / since several participants could not read the language / in which it was written.','副词修饰 adequate，表示依据道德原则或从伦理角度衡量。','知情同意涉及尊重参与者，属于伦理评估。'],['The study was ethically sound because researchers secretly enrolled people who had refused to participate.','The study was ethically unsound because researchers secretly enrolled people who had refused to participate.','违背明确拒绝违反同意原则，因此不符合伦理。'],[[1,'To act ethically is to act?',['in accordance with principles of right and wrong','without considering anyone’s rights','only for financial gain'],0,'ethically 表示合乎道德原则地。'],[1,'Which question is ethically relevant to a study?',['Did participants give informed consent?','Was the lab painted blue?','Did the report use wide margins?'],0,'参与者是否知情同意是研究伦理问题。'],[1,'Choose the natural phrase.',['ethically responsible','ethically yesterday','ethically a microscope'],0,'ethically 可修饰 responsible 这类评价性形容词。'],[1,'An ethically questionable decision is one that?',['raises concerns about right and wrong','has already been measured twice','is grammatically plural'],0,'questionable ethical status意味着道德上令人担忧。']]);
P('ethnoarchaeology','现代学术复合词，由希腊语 ethnos“人群”与 archaeology“考古学”构成，指以当代社群观察帮助解释过去物质文化。',[1,'考古学方法','Through ethnoarchaeology, researchers observed how a present-day community stored grain, then compared the wear patterns with ancient storage vessels.','研究者通过民族考古学观察当代社群如何储粮，再将磨损痕迹与古代储粮器皿比较。','Through ethnoarchaeology, researchers observed how a present-day community stored grain, / then compared the wear patterns / with ancient storage vessels.','学科名词；方法是用当代生活实践为考古材料解释提供比较线索。','研究把当代储粮方式与古代器物痕迹比较，符合其方法。'],['The team called its analysis ethnoarchaeology even though it studied only star positions and no human material culture.','The team called its analysis astronomy because it studied star positions rather than human material culture.','只研究星体位置属于天文学，不是结合人群实践和考古材料的民族考古学。'],[[1,'Ethnoarchaeology combines archaeological study with?',['observations of present-day people and their material practices','the calculation of distant star orbits','the classification of chemical elements only'],0,'它利用当代人群观察来理解过去物质文化。'],[1,'Why observe how a living community makes pots?',['The practice may help interpret traces on ancient pottery.','It proves that every ancient pot had the same owner.','It replaces the need to examine archaeological evidence.'],0,'现存实践可帮助提出对古代器物的解释，但不取代证据。'],[1,'The prefix ethno- here relates most closely to?',['a people or cultural group','a unit of electrical current','a kind of tree'],0,'ethno- 来自表示人群、民族的词根。'],[1,'Which project is ethnoarchaeological?',['comparing modern food-storage practices with ancient remains','measuring the age of stars through telescopes','translating a poem without studying artifacts'],0,'对比当代实践与古代遗存符合民族考古学。']]);
P('ethnographer','ethnography 加施事后缀 -er；ethnography 由希腊语 ethnos“人群”与 graphein“写”组成。',[1,'田野研究','The ethnographer lived in the coastal village for a year, learning local fishing routines before writing a detailed account of how families shared the catch.','民族志作者在沿海村庄生活了一年，先了解当地捕鱼日常，再撰写各家如何分享渔获的详细记录。','The ethnographer lived in the coastal village for a year, / learning local fishing routines / before writing a detailed account of how families shared the catch.','指研究并记录群体文化的人；此处强调长期田野观察。','研究者在社群中生活并写下细节，符合 ethnographer。'],['The ethnographer wrote a detailed account of the village after refusing to observe or speak with anyone there.','The travel writer wrote a brief impression of the village after refusing to observe or speak with anyone there.','拒绝田野接触却声称详记社群，不符合民族志工作；简短旅行印象更准确。'],[[1,'An ethnographer typically aims to?',['study and describe a community’s way of life','calculate the chemical mass of a metal','design a tidal power turbine'],0,'民族志作者研究并细致记录文化与日常生活。'],[1,'Which activity best fits an ethnographer?',['living with a community and documenting its practices','ranking stars by brightness','repairing a broken microscope'],0,'参与观察和文化记录是典型民族志工作。'],[1,'Choose the natural phrase.',['an ethnographer conducting fieldwork','an ethnographer boiling the data','an ethnographer of the staircase only'],0,'conduct fieldwork 是描述民族志研究的自然搭配。'],[1,'An ethnographer’s account is most directly about?',['a people and their culture','the orbit of a planet','the design of a chemical formula'],0,'其记录对象是人群文化。']]);
P('ethnographic','由 ethnography 加 -ic 构成；该学科名源于希腊语 ethnos“人群”与 graphein“写”。',[1,'社会研究','The ethnographic notes record who prepared meals, how guests were welcomed, and which stories elders told during the annual gathering.','民族志笔记记录了谁负责备餐、如何迎接客人，以及长者在年度聚会讲述哪些故事。','The ethnographic notes record who prepared meals, / how guests were welcomed, / and which stories elders told during the annual gathering.','形容词，修饰 notes、research、description 等与文化实地记录相关的名词。','记录具体习俗与互动的笔记具有民族志性质。'],['The ethnographic report contains no observations of people, customs, or social life; it lists only the lab’s electricity bills.','The accounting report contains no observations of people, customs, or social life; it lists only the lab’s electricity bills.','电费账目不涉及文化观察，用 accounting 而非 ethnographic 描述才准确。'],[[1,'Ethnographic research focuses on?',['detailed description of people’s cultural practices','the chemical structure of a single mineral','the speed of a moving escalator'],0,'ethnographic 指与民族志式文化观察和描述有关。'],[1,'Which material is ethnographic?',['field notes about household routines in a community','a table of planetary temperatures only','a receipt for laboratory equipment'],0,'关于社群日常生活的田野笔记属于民族志材料。'],[1,'Choose the appropriate noun after ethnographic.',['description','yesterday','quickly'],0,'ethnographic 是形容词，可修饰 description。'],[1,'An ethnographic interview would most likely ask about?',['local customs and everyday experience','the exact mass of an electron only','the paint code on a stair rail'],0,'民族志访谈关注文化实践和生活经验。']]);
P('ethnography','源自希腊语 ethnos“人群”与 graphein“写”，指对某一群体文化的细致记录，也指形成记录的研究方法。',[1,'人类学','The ethnography compares wedding preparations across three generations, drawing on interviews, observed ceremonies, and notes from family kitchens.','这部民族志比较了三代人的婚礼准备过程，依据包括访谈、仪式观察和家庭厨房笔记。','The ethnography compares wedding preparations across three generations, / drawing on interviews, observed ceremonies, / and notes from family kitchens.','可指书面民族志成果，也可指实地研究方法；不等于泛泛的旅游描述。','访谈、观察和细节记录共同形成对文化实践的民族志。'],['The ethnography described the culture in detail despite containing no interviews, observations, field notes, or cultural material.','The brochure described the tourist route despite containing no interviews, observations, field notes, or cultural material.','没有社群材料不能构成民族志；旅游宣传册不是文化田野记录。'],[[1,'Ethnography can refer to?',['a detailed account or study of a people’s culture','a law governing river tides','a method for measuring sound pitch'],0,'ethnography 指文化的详细记述或产生该记述的研究方法。'],[1,'Which sources might support an ethnography?',['interviews, observation, and field notes','only a list of unrelated dates','a weather forecast with no social data'],0,'民族志常综合访谈、参与观察和田野笔记。'],[1,'The element -graphy in ethnography is associated with?',['writing or description','a person who operates a lift','a chemical reaction alone'],0,'-graphy 表示书写、描述这一类形式。'],[1,'A finished ethnography is likely to explain?',['how a community’s customs and social life work','how to tune a piano by frequency alone','how an engine’s fuel is taxed'],0,'民族志成果阐述特定社群的生活与文化。']]);
P('ethnology','由希腊语 ethnos“人群”与 -logy“学科、研究”构成，指比较不同人群文化的学科。',[1,'学科比较','In ethnology, the students compared kinship terms across several societies, asking how different systems organise family relationships.','在民族学课程中，学生比较多个社会的亲属称谓，探讨不同体系如何组织家庭关系。','In ethnology, the students compared kinship terms across several societies, / asking how different systems / organise family relationships.','学科名词，通常侧重跨群体比较；与聚焦具体社群描述的 ethnography 有关联但不相同。','跨社会比较亲属制度符合民族学的比较取向。'],['The course called its close description of one household ethnology, although it made no comparison among peoples or cultures.','The course called its close description of one household ethnography, although it made no comparison among peoples or cultures.','单一社群的详细描述更接近 ethnography；ethnology 常强调不同群体间比较。'],[[1,'Ethnology is the study that often compares?',['the cultures of different peoples','the spelling of unrelated verbs','the weight of one laboratory beaker'],0,'民族学着重比较不同群体及其文化。'],[1,'A student of ethnology might compare?',['kinship systems in several societies','three brands of staircase paint','one molecule’s boiling point only'],0,'跨社会亲属体系比较符合民族学。'],[1,'Which statement distinguishes ethnology from a single-community ethnography?',['Ethnology often stresses comparison across peoples.','Ethnology means a speech praising the dead.','Ethnology is a type of tidal river.'],0,'民族学较强调跨群体比较。'],[1,'The element ethn- refers to?',['a people or cultural group','an air passage to the lungs','a saltwater chemical'],0,'ethn- 源自表示人群、民族的词根。']]);
P('ethological','由 ethology 加 -ical 构成；ethology 以希腊语 ēthos“习性、行为”与 -logy 构成，指动物行为学。',[1,'动物研究','The ethological study tracked how the young wolves greeted pack members, noting posture, distance, and changes in behaviour after feeding.','这项动物行为学研究追踪幼狼如何迎接群体成员，记录姿势、距离及进食后的行为变化。','The ethological study tracked how the young wolves greeted pack members, / noting posture, distance, / and changes in behaviour after feeding.','形容词，指与动物行为研究有关；不等于伦理学的 ethical。','对狼群姿势和互动的观察属于动物行为学。'],['The ethological paper analysed whether the research decision was morally right, without studying any animal behaviour.','The ethical paper analysed whether the research decision was morally right, without studying any animal behaviour.','判断研究行为是否合乎道德属于 ethical 议题，而非动物行为学 ethological。'],[[1,'An ethological observation concerns?',['how an animal behaves','whether a choice is morally fair','how a river mouth changes with tides'],0,'ethological 指与动物行为学有关。'],[1,'Which topic is ethological?',['courtship signals observed in wild birds','the legal ethics of a court ruling','the geometry of a copper plate'],0,'野鸟求偶信号属于动物行为研究。'],[1,'Ethological research most directly studies?',['behaviour in animals, often in natural settings','human tax exemptions only','the sound of a spoken eulogy'],0,'ethology 是研究动物行为的科学。'],[1,'Choose the word that differs in meaning from ethological.',['ethical','behavioural','zoological'],0,'ethical 讨论道德，是形似但不同的词。']]);
P('ethology','ethology 由希腊语 ēthos“习性、行为”与 -logy“研究”构成，指动物行为学。',[1,'生物学','The field team practised ethology by watching nesting birds from a blind, recording how adults divided food among the chicks.','研究团队通过隐蔽观察筑巢鸟类开展动物行为学研究，记录成鸟如何把食物分给雏鸟。','The field team practised ethology by watching nesting birds from a blind, / recording how adults divided food / among the chicks.','学科名词，研究动物的行为，尤其关注其自然环境中的行为。','观察鸟类的觅食与育幼方式属于动物行为学。'],['The researchers called their study ethology, although it examined only the ethics of human consent and no animal behaviour.','The researchers called their study research ethics, since it examined human consent and no animal behaviour.','人体研究的同意规范属研究伦理，不是研究动物行为的 ethology。'],[[1,'Ethology is the scientific study of?',['animal behaviour','the beauty of paintings','the taxation of imports'],0,'ethology 指科学研究动物行为。'],[1,'Which observation belongs to ethology?',['how ants divide work in a colony','how a court interprets a contract','how copper reacts to acid in a print plate'],0,'蚂蚁群体的分工是动物行为现象。'],[1,'A biologist studying courtship in wild fish works in?',['ethology','eulogy','euphony'],0,'野外鱼类求偶行为属于 ethology。'],[1,'The Greek element in ethology is associated with?',['habit or character','a river mouth','a musical instrument'],0,'词源 ēthos 与习性、行为相关。']]);
P('eucalyptus','属名来自希腊语 eu“好”与 kalyptos“覆盖”，指花蕾盖有帽状结构的植物，常称桉树。',[1,'植物学','The eucalyptus released a sharp scent when the ranger crushed one fallen leaf, and its narrow crown stood above the dry hillside.','护林员捏碎一片落叶时，桉树散发出浓烈气味；它狭长的树冠高耸在干燥山坡上。','The eucalyptus released a sharp scent / when the ranger crushed one fallen leaf, / and its narrow crown stood above the dry hillside.','可数名词，指桉属树木；不能仅凭叶片有香味就判断其他树种也是桉树。','香叶和树形符合常见桉树描述。'],['The botanist identified the eucalyptus as a leafless fish that grows beneath the sea.','The botanist identified the eucalyptus as an aromatic-leaved tree.','eucalyptus 是树木属名，不是海鱼；换成树木描述即可纠正。'],[[1,'A eucalyptus is a type of?',['tree','tidal inlet','formal funeral speech'],0,'eucalyptus 指桉属树木。'],[1,'Which feature is often associated with eucalyptus?',['aromatic leaves','metallic scales','moving steps'],0,'许多桉树的叶片有芳香气味。'],[1,'A ranger crushes a eucalyptus leaf and notices?',['a strong plant scent','a legal exemption','a river current'],0,'桉树叶常有明显气味。'],[1,'The name eucalyptus is commonly linked to the idea of?',['well covered, referring to the bud cap','well spoken, referring to a eulogy','evenly shared, referring to a division'],0,'属名词源涉及花蕾的帽状覆盖物。']]);
P('eukaryote','现代生物学术语，借自希腊语 eu“良好/真正”与 karyon“核”，指细胞具有膜包被细胞核的生物。',[1,'细胞生物学','A yeast cell is a eukaryote: microscopy shows its genetic material enclosed within a membrane-bound nucleus.','酵母细胞是真核生物；显微镜下可见其遗传物质位于膜包被的细胞核内。','A yeast cell is a eukaryote: / microscopy shows its genetic material / enclosed within a membrane-bound nucleus.','可数名词；与没有膜包细胞核的原核生物相区别。','酵母有膜包细胞核，符合真核生物定义。'],['The microbiology text classified a bacterium as a eukaryote because it lacks any membrane-bound nucleus.','The microbiology text classified a bacterium as a prokaryote because it lacks any membrane-bound nucleus.','细菌没有膜包细胞核，属于原核生物而非 eukaryote。'],[[1,'A eukaryote has cells containing?',['a membrane-bound nucleus','no genetic material at all','only a rigid outer shell and no internal structures'],0,'真核细胞的关键特征是具膜包被的细胞核。'],[1,'Which organism is a eukaryote?',['a yeast','a typical bacterium','a bare virus particle'],0,'酵母是真核生物；典型细菌是原核生物。'],[1,'The prefix eu- in eukaryote is historically related to?',['good or true','river or tide','sound or voice'],0,'eu- 源自希腊语，含“好、真正”之意。'],[1,'A cell sample with a nucleus enclosed by a membrane supports identifying it as?',['eukaryotic','prokaryotic','acellular'],0,'膜包被的细胞核是真核细胞的识别特征。']]);
P('eukaryotic','eukaryote 加形容词后缀 -ic；名称结合希腊语 eu“真正”与 karyon“核”。',[1,'遗传学','The eukaryotic cells formed a clear nucleus under the microscope, unlike the bacteria in the neighbouring culture dish.','显微镜下这些真核细胞形成清晰的细胞核，不同于旁边培养皿中的细菌。','The eukaryotic cells formed a clear nucleus under the microscope, / unlike the bacteria / in the neighbouring culture dish.','形容词，描述具膜包细胞核的细胞或生物。','细胞核可见且有膜包被，体现 eukaryotic。'],['The biologist called the bacterium eukaryotic even though it has no membrane-bound nucleus.','The biologist called the bacterium prokaryotic even though it has no membrane-bound nucleus.','无膜包被细胞核是原核特征，应称 prokaryotic。'],[[1,'A eukaryotic cell contains?',['a nucleus enclosed by a membrane','no cell interior of any kind','a tiny animal instead of genetic material'],0,'eukaryotic 指具有膜包细胞核的。'],[1,'Which description is eukaryotic?',['the cell has membrane-bound internal compartments','the organism is a bacterium with no nucleus','the sample is only a mineral crystal'],0,'膜包被的内部细胞结构是真核特征。'],[1,'Choose the accurate contrast.',['Eukaryotic cells have a nucleus; typical bacterial cells do not.','Eukaryotic means able to live only in water.','Eukaryotic describes an organism with no cells.'],0,'真核与典型原核细胞的核心差别在细胞核。'],[1,'Which noun does eukaryotic most directly modify?',['cell','eulogy','estuary'],0,'eukaryotic 通常修饰 cell 或 organism。']]);
P('eulogy','源自希腊语 eulogia“赞美之辞”，由 eu“好”与 logos“言辞”组成，指正式颂词，尤指悼词。',[1,'追思仪式','In her eulogy, the professor’s former student recalled how she opened the laboratory to young researchers who had nowhere else to work.','在悼词中，这位教授以前的学生回忆她如何向无处开展研究的年轻学者开放实验室。','In her eulogy, the professor’s former student recalled / how she opened the laboratory / to young researchers who had nowhere else to work.','可数名词，正式赞扬某人；常用于葬礼或追思场合。','演讲赞颂逝者对学生的帮助，符合悼词义。'],['The family delivered a eulogy to condemn the deceased and list every insult he had ever made.','The family delivered a denunciation to condemn the deceased and list every insult he had ever made.','谴责和列举侮辱不是赞扬性的 eulogy，denunciation 才符合。'],[[1,'A eulogy is usually?',['a formal speech praising someone, often after death','a list of taxes on imported goods','a study of animal behaviour'],0,'eulogy 是正式颂词，常为悼词。'],[1,'At a memorial, a speaker giving a eulogy might?',['recall the person’s admirable qualities','announce the building’s fire exits only','measure the width of the coffin'],0,'悼词通常回忆逝者的优点和贡献。'],[1,'The Greek element eu- in eulogy carries the sense of?',['good or well','distant or far','underwater'],0,'eulogy 的构词含 eu“好、善”。'],[1,'Choose the natural collocation.',['deliver a eulogy','evaporate a eulogy','etch a eulogy into a river'],0,'常说 deliver/give a eulogy。']]);
P('euphonious','希腊语 eu“好”与 phōnē“声音”构成 euphonious，形容声音悦耳、和谐。',[1,'诗歌朗读','The translator chose a euphonious phrase whose soft consonants and balanced vowels made it easy to read aloud.','译者选了一个悦耳的短语，其中柔和的辅音与匀称的元音让朗读十分顺口。','The translator chose a euphonious phrase / whose soft consonants and balanced vowels / made it easy to read aloud.','形容词，修饰词语、名字或声音，强调听觉上的悦耳。','柔和音节组合使短语适合朗读，符合 euphonious。'],['The euphonious alarm was painfully grating and made everyone cover their ears.','The harsh alarm was painfully grating and made everyone cover their ears.','刺耳令人不适与悦耳相反，用 harsh 才贴合。'],[[1,'A euphonious name sounds?',['pleasant and harmonious','impossible to pronounce because it has no vowels','like a loud mechanical alarm'],0,'euphonious 表示悦耳、和谐。'],[1,'Which sentence is euphonious?',['The phrase flows smoothly when read aloud.','The siren produces a jarring shriek.','The sentence contains no sound at all.'],0,'顺口、流畅的声音效果体现 euphonious。'],[1,'The parts eu- and phon- point toward?',['good sound','tidal soil','written history'],0,'构词包含“好”与“声音”的含义。'],[1,'Choose the closest synonym.',['melodious','abrasive','silent'],0,'melodious 与 euphonious 都强调听觉悦耳。']]);
P('euphony','由希腊语 eu“好”与 phōnē“声音”组成，指言语或诗句的悦耳、和谐效果。',[1,'修辞与音韵','The poet revised the line for euphony, replacing a cluster of harsh consonants with a rhythm that could be spoken smoothly.','诗人为了音韵悦耳而修改诗行，把一串刺耳辅音换成更容易顺畅朗读的节奏。','The poet revised the line for euphony, / replacing a cluster of harsh consonants / with a rhythm that could be spoken smoothly.','不可数名词，强调声音效果本身；常与 cacophony 对照。','顺畅音节形成愉悦声音，体现 euphony。'],['The critic praised the poem’s euphony because every line was deliberately harsh and painful to hear.','The critic praised the poem’s cacophony because every line was deliberately harsh and painful to hear.','刺耳不和谐是 cacophony；euphony 指悦耳和谐。'],[[1,'Euphony is the quality of?',['pleasant, harmonious sound','a person being exempt from tax','a river affected by tides'],0,'euphony 指声音的悦耳和谐。'],[1,'A writer may revise a sentence for euphony to improve?',['how smoothly it sounds when read aloud','its legal ownership','the amount of water it contains'],0,'音韵修改关注朗读时的声音流畅度。'],[1,'Which pair expresses contrasting sound qualities?',['euphony and cacophony','euphony and eucalyptus','euphony and estivation'],0,'cacophony 指刺耳杂乱的声音，与 euphony 对照。'],[1,'The Greek element phon- relates to?',['sound or voice','a river mouth','a human group'],0,'phon- 来自表示声音的希腊词根。']]);
P('European','由 Europe 加 -an 构成，指与欧洲相关的，也可作可数名词指欧洲人。',[2,'人口统计','The survey interviewed each European separately, rather than treating the continent’s many languages and national backgrounds as one experience.','调查逐一采访每位欧洲人，没有把这片大陆众多语言和国籍背景当作同一种经历。','The survey interviewed each European separately, / rather than treating the continent’s many languages / and national backgrounds as one experience.','European s2 为人，首字母通常大写；作形容词时修饰文化、制度等。','句中 each European 指一位来自欧洲的人。'],['The guide called the river basin a European even though the word was being used to name a person from Europe.','The guide called the river basin European even though the word was being used to describe a geographical feature.','描述地理区域时需用形容词 European；冠词 a 把它误作人。'],[[1,'A European policy is a policy?',['related to Europe','written only in Greek','about a particular tree genus'],0,'European 可作形容词，表示与欧洲有关。'],[2,'“Several Europeans attended” refers to?',['several people from Europe','several rivers entering the sea','several musical sounds'],0,'European 作名词时指欧洲人。'],[1,'Choose the correctly capitalised form.',['European history','european history','EuropeAn history'],0,'国名及其派生形容词 European 通常大写。'],[2,'Which sentence uses European as a noun?',['A European spoke at the meeting.','The museum displayed European pottery.','They debated European policy.'],0,'a European 指一个欧洲人；其余句中为形容词。']]);
P('eusocial','现代生物学术语，结合 eu“真正、完善”与 social，描述具有分工、世代重叠及合作育幼的社会结构。',[1,'昆虫学','The bee colony is eusocial: queens reproduce, workers perform most other tasks, and adults cooperate in caring for the young.','蜂群具有真社会性：蜂后负责繁殖，工蜂承担多数其他任务，成虫共同照护幼体。','The bee colony is eusocial: / queens reproduce, workers perform most other tasks, / and adults cooperate in caring for the young.','形容词，常描述蚂蚁、蜜蜂等群居昆虫；核心是繁殖分工及合作育幼。','蜂群出现明确繁殖分工与共同育幼，符合 eusocial。'],['The solitary wasp was described as eusocial even though each female lived alone and never cared for another’s young.','The solitary wasp was described as non-social even though each female lived alone and never cared for another’s young.','独居且不协作的生活方式不符合真社会性。'],[[1,'A eusocial insect group typically has?',['reproductive division of labour and cooperative care of young','no interaction among individuals','only one insect with no offspring'],0,'真社会性包含繁殖分工和合作照料幼体。'],[1,'Which colony is most clearly eusocial?',['workers help raise offspring produced by a queen','each individual avoids all group contact','all members reproduce independently with no cooperation'],0,'蜂后繁殖、工蜂合作育幼是典型结构。'],[1,'Eusociality is commonly discussed in studies of?',['ants and honeybees','river deltas only','musical vowels'],0,'蚂蚁和蜜蜂是常见真社会性昆虫。'],[1,'The eu- in eusocial suggests a sense of?',['true or well-developed','distant from the sea','written by hand'],0,'现代术语用 eu- 强调其高度组织化的社会性。']]);
P('euthanasia','源自希腊语 eu“好”与 thanatos“死亡”，英语借自新拉丁语；指为解除不可治愈痛苦而有意结束生命。',[1,'医学伦理','The ethics panel discussed euthanasia in the context of a terminal illness, distinguishing the term from ordinary pain relief and palliative care.','伦理委员会结合绝症讨论安乐死，并将这个概念与常规止痛和姑息照护区分开。','The ethics panel discussed euthanasia in the context of a terminal illness, / distinguishing the term from ordinary pain relief / and palliative care.','敏感的医学伦理名词；定义聚焦有意结束生命以解除难以缓解的痛苦。','讨论明确区分有意结束生命与减轻症状的照护。'],['The report called routine treatment for pain euthanasia even though the treatment neither intended nor caused death.','The report called routine treatment for pain palliative care even though the treatment neither intended nor caused death.','不以结束生命为目的的常规症状控制属于照护，不是 euthanasia。'],[[1,'In its medical-ethics sense, euthanasia refers to?',['deliberately ending life to relieve incurable suffering','any medicine that reduces a headache','a speech praising someone at a funeral'],0,'该词指以解除无法治愈的痛苦为目的有意结束生命。'],[1,'Which distinction is important when discussing euthanasia?',['pain relief is not automatically an intention to end life','every form of care has the same meaning','a eulogy is a medical procedure'],0,'减轻痛苦的治疗不等同于有意结束生命。'],[1,'The word’s Greek elements combine ideas of?',['good and death','river and mouth','sound and writing'],0,'词源由 eu“好”与 thanatos“死亡”构成。'],[1,'A careful discussion of euthanasia belongs most directly to?',['medical ethics','tree identification','acoustic poetry'],0,'这是医学伦理讨论中的术语。']]);
P('evacuation','由 evacuate 加 -ion；其拉丁词根 vacuus 意为“空”，现代常指有组织地撤离危险地点。',[1,'应急管理','The evacuation began before the river reached the lower road, and wardens checked each shelter to make sure no residents were left behind.','河水涨到低处道路前，撤离行动已经开始；疏散员逐一检查避难点，确保没有居民被遗漏。','The evacuation began before the river reached the lower road, / and wardens checked each shelter / to make sure no residents were left behind.','可数或不可数名词，常与 evacuation order、route、shelter 搭配。','预先把居民有组织转移到安全处就是 evacuation。'],['Officials called it an evacuation while instructing every resident to remain inside the flooded district.','Officials called it a shelter-in-place order while instructing every resident to remain inside the district.','要求留在原地避险不是撤离 evacuation，而是就地避难。'],[[1,'An evacuation is an organised?',['movement of people away from danger','movement of water into a sealed bottle','ceremony praising a deceased person'],0,'evacuation 指把人从危险地区有组织地撤走。'],[1,'When might officials order an evacuation?',['when a wildfire threatens nearby homes','when the weather is pleasant and safe','when a museum opens a new exhibit'],0,'逼近居民区的野火构成撤离理由。'],[1,'Choose the natural phrase.',['evacuation route','evacuation tastefully','evacuation a scientist'],0,'route 可指撤离路线。'],[1,'During an evacuation, wardens should first help people reach?',['a safer place','the most dangerous area','an unrelated tax office'],0,'撤离的目的在于离开危险并到达安全地点。']]);
P('evaluation','由 evaluate 加 -ion；evaluate 经法语与拉丁语 valere“有价值、有力量”关联，指对质量或效果作判断。',[1,'项目评估','The evaluation compared the pilot programme’s costs with attendance records and interviews before recommending whether it should expand.','评估把试点项目的费用与出勤记录、访谈结果进行比较，再建议是否扩大实施。','The evaluation compared the pilot programme’s costs / with attendance records and interviews / before recommending whether it should expand.','可数名词，可指一次评估或评估过程；判断依据应与目标相关。','比较投入、记录和访谈以判断项目成效，体现 evaluation。'],['The evaluation judged the programme successful without examining any results, costs, or participant feedback.','The guess judged the programme successful without examining any results, costs, or participant feedback.','没有证据支持的判断是猜测，而不是基于资料的评估。'],[[1,'An evaluation aims to judge?',['how good, useful, or successful something is','how a word is pronounced in another language','which people were born in Europe'],0,'evaluation 是对质量、用途或成效作判断。'],[1,'Which information would strengthen a programme evaluation?',['costs, outcome data, and participant feedback','the evaluator’s favourite colour only','an unrelated river map'],0,'与目标相关的数据和反馈可支持评估。'],[1,'Choose the natural phrase.',['an evaluation of the results','an evaluation from the results is blue','an evaluate of the results'],0,'名词 evaluation 常与 of 连用。'],[1,'The report’s evaluation concluded that the treatment?',['worked better than the comparison method','was a tree species','had no measurable outcome but was declared proven'],0,'评估可以比较处理效果并据证据得出结论。']]);
P('evaluative','由 evaluate/evaluation 加形容词后缀 -ive 构成，表示表达或依据价值判断的。',[1,'语言分析','The researcher separated evaluative comments such as “excellent” from factual observations such as “the sample weighed five grams.”','研究者把“极佳”这类评价性评论与“样本重五克”这类事实观察分开。','The researcher separated evaluative comments such as “excellent” / from factual observations / such as “the sample weighed five grams.”','形容词，修饰 language、judgment、statement 等，指出含有价值评价。','excellent 表达主观好坏判断，属于 evaluative wording。'],['The sentence “the sample weighs five grams” is purely evaluative because it gives a measurable quantity without judging its worth.','The sentence “the sample weighs five grams” is factual because it gives a measurable quantity without judging its worth.','可测量的重量陈述事实，不含对好坏价值的判断。'],[[1,'An evaluative statement expresses?',['an assessment of worth or quality','only a measured fact with no judgment','a person’s birthplace'],0,'evaluative 表示含有评价或价值判断的。'],[1,'Which word makes the sentence evaluative?',['“excellent” in “an excellent result”','“five” in “five samples”','“Tuesday” in “on Tuesday”'],0,'excellent 直接表达质量评价。'],[1,'A factual report is often distinguished from evaluative language because the latter?',['judges or assesses rather than merely describes','contains only dates','cannot be written down'],0,'评价性语言进行价值判断，不只是客观描述。'],[1,'Choose the appropriate collocation.',['evaluative judgment','evaluative a river','evaluative yesterday'],0,'evaluative 常修饰 judgment。']]);
P('evanescent','源自拉丁语 evanescere“逐渐消失、化为乌有”，指很快消散或消失的。',[1,'自然观察','The evanescent rainbow faded within minutes as the rain stopped and the low evening sun slipped behind the ridge.','雨停后低处的夕阳躲到山脊后，短短几分钟内那道转瞬即逝的彩虹便淡去了。','The evanescent rainbow faded within minutes / as the rain stopped / and the low evening sun slipped behind the ridge.','正式形容词，常形容光、气味、情绪等短暂且容易消散的事物。','彩虹几分钟即消失，表现 evanescent 的短暂性。'],['The evanescent monument remained unchanged for ten thousand years and showed no sign of disappearing.','The enduring monument remained unchanged for ten thousand years and showed no sign of disappearing.','长期不变与快速消散相反；enduring 更适合。'],[[1,'An evanescent impression is one that?',['vanishes quickly','lasts permanently','can be weighed exactly'],0,'evanescent 表示短暂、容易消失。'],[1,'Which is most likely evanescent?',['a scent that disappears within minutes','a mountain range lasting millions of years','a sealed stone inscription'],0,'很快消散的气味是短暂事物。'],[1,'The closest opposite of evanescent is?',['lasting','fleeting','transient'],0,'lasting 表示持续很久，与短暂相反。'],[1,'Choose the natural phrase.',['an evanescent glow','an evanescent concrete foundation lasting centuries','evanescent more evenly'],0,'短暂微光可自然称作 evanescent glow。']]);
P('evaporation','由 evaporate 加 -ion；evaporate 经拉丁语 vapor“蒸气”关联，指液体转成气体，也可比喻逐渐消失。',[1,'物理过程','Even without boiling, evaporation from the shallow dish slowly reduced the water level while the room remained warm and dry.','即使没有沸腾，浅盘中的水也因蒸发而慢慢减少；当时室内温暖而干燥。','Even without boiling, evaporation from the shallow dish / slowly reduced the water level / while the room remained warm and dry.','s1 为液体汽化过程；发生在液体表面，可低于沸点。','水位下降而无沸腾，说明液体正在蒸发。'],['The scientist attributed the falling water level to evaporation even though the sealed liquid had turned into ice.','The scientist attributed the falling water level to freezing even though the sealed liquid had turned into ice.','液体变成固体是 freezing，不是液体转为气体的 evaporation。'],[[1,'Evaporation changes a substance from?',['liquid to gas','solid to liquid only','gas to solid directly'],0,'evaporation 是液体变为气体的过程。'],[1,'Can evaporation occur below a liquid’s boiling point?',['Yes, at its surface.','No; only boiling can remove liquid molecules.','Only if the liquid becomes a solid first.'],0,'表面蒸发可在低于沸点时发生。'],[2,'“The evaporation of public interest” means?',['public interest gradually disappeared','water changed into steam','a crowd moved to a new venue'],0,'此处是“逐渐消失”的比喻义。'],[1,'Which condition often speeds evaporation from an open dish?',['warm, dry moving air','a tightly sealed container','lower exposed surface area with no airflow'],0,'温暖、干燥且有流动的空气通常利于蒸发。']]);
P('evaporator','由 evaporate 加施事/设备后缀 -or 构成，指使液体蒸发、常用于浓缩或制冷的装置。',[1,'工程设备','The evaporator removed water from the fruit juice under reduced pressure, concentrating the flavour without exposing the mixture to excessive heat.','蒸发器在减压条件下从果汁中除去水分，使其浓缩，同时避免混合物受到过高温度。','The evaporator removed water from the fruit juice under reduced pressure, / concentrating the flavour / without exposing the mixture to excessive heat.','可数设备名词；具体设计随工业用途变化，但核心过程涉及蒸发。','从果汁中移除水分以实现浓缩，是蒸发器的用途。'],['The technician called the condenser an evaporator because it changed vapour back into liquid.','The technician called the condenser a condenser because it changed vapour back into liquid.','把蒸气冷凝成液体的设备是 condenser；evaporator 促使液体蒸发。'],[[1,'An evaporator is equipment used to?',['make a liquid evaporate, often to concentrate it','turn all vapour into a solid block','measure the pitch of a song'],0,'evaporator 促使液体蒸发。'],[1,'In food processing, an evaporator may?',['remove water to concentrate juice','add water to dilute every product','measure a river’s tidal range'],0,'蒸发器可除水浓缩液体食品。'],[1,'Which device does the opposite phase-change job in a cooling circuit?',['a condenser','a eulogy','a eucalyptus'],0,'冷凝器将蒸气变回液体，与蒸发侧过程相反。'],[1,'The suffix -or in evaporator commonly names?',['a device or agent that performs an action','a plural of a tree','a past tense verb'],0,'-or 常构成执行动作的人或设备名称。']]);
P('evasion','源自拉丁语 evadere“逃脱、避开”，经法语进入英语；可指逃避责任，也可指回避问题的话。',[2,'采访','Asked whether the figures included unpaid overtime, the director gave an evasion about “the spirit of the project” and never answered the question.','当被问及数字是否包括无偿加班时，主管用“项目精神”搪塞，没有回答问题。','Asked whether the figures included unpaid overtime, / the director gave an evasion / about “the spirit of the project” and never answered the question.','s2 为回避直接回答的话；s1 可指逃避义务或责任。','答非所问的说辞是 evasion 的名词义。'],['The director’s evasion directly answered the question with precise numbers and no attempt to avoid it.','The director’s clarification directly answered the question with precise numbers and no attempt to avoid it.','清楚直接的回答不是回避；clarification 更符合。'],[[1,'Tax evasion is?',['deliberately avoiding a tax obligation','paying an assessed tax on time','estimating a company’s value'],0,'evasion s1 可指逃避纳税义务。'],[2,'An evasive answer is an evasion when it?',['avoids giving a direct response','clearly supplies the requested facts','asks a relevant follow-up question'],0,'s2 指回避直接回答的说法。'],[2,'“That is an evasion” most likely criticises a reply for being?',['deliberately indirect','fully documented','grammatically plural'],0,'evasion 可指借口式的回避回答。'],[1,'Choose the natural collocation.',['evasion of duty','evasion to explain clearly','evasion a deadline by completing it'],0,'evasion 常与 of 连用，表示逃避某种义务。']]);
P('evasive','由 evade 加 -ive 构成；evade 源自拉丁语 evadere“脱身”，可指回答含糊回避，也可指采取行动躲避。',[1,'新闻采访','The spokesperson became evasive when reporters asked who had approved the contract, repeating that “the process is ongoing.”','记者询问是谁批准合同时，发言人开始含糊回避，只反复说“流程仍在进行”。','The spokesperson became evasive / when reporters asked who had approved the contract, / repeating that “the process is ongoing.”','s1 描述不肯正面回答；s2 可描述躲避打击、追赶或碰撞的动作。','发言人没有回答批准者是谁，属于语言上的回避。'],['The spokesperson was evasive and supplied a direct name, date, and signed document in response to every question.','The spokesperson was forthcoming and supplied a direct name, date, and signed document in response to every question.','提供明确资料是坦率配合，不是 evasive。'],[[1,'An evasive reply is one that?',['avoids answering clearly','gives all relevant facts directly','repeats the question accurately'],0,'evasive s1 指不愿清楚作答。'],[2,'An evasive manoeuvre is made to?',['avoid a collision, blow, or pursuer','deliver a speech of praise','concentrate a liquid by heating'],0,'evasive s2 指为了躲避危险而采取的动作。'],[1,'Which speaker sounds evasive?',['one who changes the subject whenever asked about the missing funds','one who provides the receipts and answers each question','one who admits exactly what is unknown'],0,'一再转移话题是回避直接回答。'],[1,'Choose the correct collocation.',['an evasive answer','an evasive answer the question clearly','evasive into the answer'],0,'an evasive answer 是自然搭配。']]);
P('evenly','由 even 加副词后缀 -ly；even 源自古英语 efne“平坦、相等”，副词表示均匀或均等地。',[1,'烹饪','Spread the batter evenly across the pan so that the thin centre and thicker edges finish cooking at nearly the same time.','把面糊均匀铺满平底锅，这样薄的中心部分和较厚的边缘就能差不多同时熟透。','Spread the batter evenly across the pan / so that the thin centre and thicker edges / finish cooking at nearly the same time.','s1 指分布或表面无明显差异；s2 指份额、程度相同。','均匀铺开可避免厚薄差异造成受热不一。'],['The cook distributed the batter evenly by pouring it all into one corner of the pan.','The cook distributed the batter unevenly by pouring it all into one corner of the pan.','面糊全部倒在一角是分布不均；加 un- 是最小纠正。'],[[1,'To spread paint evenly is to spread it?',['in a regular, uniform layer','only along one small edge','in alternating lumps and bare patches'],0,'evenly s1 表示均匀地。'],[2,'If two teams are evenly matched, they are?',['about equal in ability','both made of the same number of letters','playing at different times'],0,'evenly s2 表示程度或实力相当。'],[1,'Which instruction uses evenly in its surface-distribution sense?',['Coat the bread evenly with butter.','Divide the prize evenly between the winners.','The teams were evenly matched.'],0,'给面包均匀涂抹属于分布均匀义。'],[2,'A sum split evenly among four people gives each?',['an equal share','a different random share','no money at all'],0,'均等分配意味着每人份额相等。']]);
P('evenness','由 even 加名词后缀 -ness 构成，表示表面平整、变化稳定或分配均等的性质。',[1,'测量','The mason checked the evenness of the tiled floor with a long level, finding one raised corner before the grout had set.','泥瓦匠用长水平尺检查瓷砖地面的平整度，在填缝剂凝固前发现一个翘起的角。','The mason checked the evenness of the tiled floor / with a long level, / finding one raised corner before the grout had set.','不可数性质名词；可指平整、均匀、稳定，也可指公平无偏。','检查地面高低一致性是在检查 evenness。'],['The unevenness of the floor meant every tile sat at exactly the same height with no bumps or gaps.','The evenness of the floor meant every tile sat at exactly the same height with no bumps or gaps.','每块砖高度相同且无凸起表示平整，而不是 unevenness。'],[[1,'The evenness of a surface describes?',['how smooth and level it is','how expensive it is','who owns the building'],0,'evenness s1 可指表面平坦、均匀的性质。'],[1,'A sound engineer may adjust a tone’s evenness to reduce?',['sudden changes in volume','the number of players','the room’s legal capacity'],0,'声音的稳定均匀可减少突变。'],[1,'Which situation demonstrates evenness in distribution?',['each household receives the same amount','one household receives everything','the amounts are assigned without checking'],0,'份额相等体现分配均等。'],[1,'The suffix -ness turns even into a noun naming?',['a quality or state','a person who performs an action','a past event'],0,'-ness 通常把形容词变为表示性质的名词。']]);
P('eventful','由 event 加 -ful 构成；event 经法语源自拉丁语 eventus“结果、发生之事”，eventful 指发生许多重要事情的。',[1,'旅途','Their eventful crossing included a broken compass, a brief rescue by a fishing boat, and a night spent waiting for the weather to clear.','他们这趟多事的横渡途中，指南针坏了，曾由渔船短暂救助，还等了一夜才等到天气转晴。','Their eventful crossing included a broken compass, / a brief rescue by a fishing boat, / and a night spent waiting for the weather to clear.','形容一段时期或经历中事情繁多；既可有好事，也可包含麻烦。','横渡经历充满多项显著事件，体现 eventful。'],['The eventful afternoon passed with nothing happening at all and no change in the schedule.','The uneventful afternoon passed with nothing happening at all and no change in the schedule.','毫无事情发生应称 uneventful；缺少 un- 才是错误。'],[[1,'An eventful trip is one that?',['contains many notable happenings','is guaranteed to be completely boring','takes place only at an event venue'],0,'eventful 表示经历中事情多、值得注意。'],[1,'Which year sounds eventful?',['one with a move, a new job, and several major trips','one in which nothing changes or happens','one consisting only of a date on a calendar'],0,'多项重要经历让这一年显得 eventful。'],[1,'Does eventful necessarily mean happy?',['No; important events may also be difficult.','Yes; every event must be joyful.','Yes; it means no event happened.'],0,'eventful 说事情多，不保证事情都是愉快的。'],[1,'Choose the natural opposite.',['uneventful','eventfully','eventish'],0,'uneventful 表示平淡、没发生什么特别的事。']]);
P('eventuality','由 eventual 加 -ity 构成；eventual 源自拉丁语 eventus“结果”，eventuality 指可能出现的一种情况。',[1,'应急准备','The contract includes a backup supplier for the eventuality that the primary factory cannot deliver parts during the winter shutdown.','合同为主要工厂在冬季停产期间无法交货这一可能情况安排了备用供应商。','The contract includes a backup supplier / for the eventuality that the primary factory cannot deliver parts / during the winter shutdown.','可数名词，常见结构 in the eventuality that…，指需要预备的可能情况。','备用供应商针对可能发生的无法交货情形，符合 eventuality。'],['The emergency plan ignored every possible eventuality and therefore listed detailed actions for all of them.','The emergency plan ignored every possible eventuality and therefore listed no detailed actions for any of them.','称“忽略”却又给所有情况列出详细行动，语义矛盾；补 no 纠正。'],[[1,'An eventuality is?',['something that may happen','a past event that certainly occurred','a person who evaluates a project'],0,'eventuality 指可能发生的事。'],[1,'A contingency plan prepares for?',['an unwanted eventuality','a sound that is pleasing','a tree’s aromatic leaves'],0,'应急预案针对可能发生的意外情况。'],[1,'Complete the formal phrase: “in the eventuality ___ a delay.”',['of','at','to'],0,'常用 in the eventuality of something。'],[1,'Why include a spare pump for one eventuality?',['The main pump might fail.','The spare pump is a speech.','The pump changes a verb into a noun.'],0,'备用设备是为主设备可能故障作准备。']]);
P('evidently','由 evident 加 -ly 构成；evident 源自拉丁语 evidens“显而易见的”，副词可表示明显地或据迹象看来。',[2,'调查判断','The porch light was on and fresh footprints crossed the snow; evidently, someone had entered the cabin after the caretaker left.','门廊灯亮着，雪地里还有新脚印；看来管理员离开后有人进过小屋。','The porch light was on and fresh footprints crossed the snow; / evidently, someone had entered the cabin / after the caretaker left.','s1 可表示明显地；s2 常引出根据已有证据作出的推断，未必是直接目击。','脚印和亮灯是迹象，推断有人进入，体现 s2。'],['Evidently, the empty room was occupied because no one and nothing could be seen inside it.','Apparently, the room was empty because no one and nothing could be seen inside it.','无人无物可见支持房间为空；原句推断方向自相矛盾。'],[[1,'“The crack is evidently visible” means it is?',['clearly able to be seen','impossible to notice','a sound from a musical instrument'],0,'evidently s1 表示明显地、清楚可见地。'],[2,'A report says “Evidently, the gate was left open.” This signals?',['an inference from available clues','a fact directly measured as a temperature','a command to open another gate'],0,'句首 evidently 可标出依据迹象作出的推断。'],[2,'Which evidence could make someone say “Evidently, the dog got out”?',['the open gate and muddy paw prints outside','a sealed gate and clean floor','a map showing the river’s source'],0,'开门与外部爪印共同支持该推断。'],[1,'Choose a close adverb in “The label was evidently damaged.”',['clearly','secretly','eventually'],0,'evidently s1 与 clearly 接近。']]);
P('evince','源自拉丁语 evincere“证明、取得胜利”，经法语影响进入英语，现指显露出原本未明说的情感、品质或意图。',[1,'文学评论','Her careful questions evince genuine curiosity about the archive’s workers, rather than a desire merely to finish the interview quickly.','她细致的提问显露出对档案馆工作人员的真切好奇，而不只是急于结束访谈。','Her careful questions evince genuine curiosity / about the archive’s workers, / rather than a desire merely to finish the interview quickly.','正式及物动词，常接 emotion、quality、interest、concern 等抽象名词。','提问表现出内在的好奇心，体现 evince。'],['The report evinced no concern by explicitly expressing deep concern for the families affected.','The report evinced clear concern by explicitly expressing deep concern for the families affected.','明确表达深切关心就是 evince concern，与 no concern 矛盾。'],[[1,'To evince patience is to?',['show or reveal patience','hide every sign of patience','measure how long a clock runs'],0,'evince 指表现、显示出某种品质或情感。'],[1,'Which action may evince concern?',['asking whether the injured worker received care','changing the subject whenever injury is mentioned','destroying the medical report'],0,'询问伤者是否获照护表现出关心。'],[1,'Choose the natural object of evince.',['enthusiasm','from enthusiasm','to enthuse'],0,'evince 是及物动词，可直接接 enthusiasm。'],[1,'“The evidence evinced a pattern” means it?',['revealed the pattern','concealed the pattern','celebrated the pattern in a speech'],0,'evince 在此表示显露、显示出。']]);
P('eviscerate','来自拉丁语 eviscerare“取出内脏”，由 ex- 与 viscera“内脏”构成；引申为抽去论点或法律的实质。',[2,'法律评论','The amendment did not repeal the law outright, but critics said it would eviscerate the protections by removing the enforcement powers.','修正案没有直接废除法律，但批评者认为它会通过取消执法权而抽空法律保护。','The amendment did not repeal the law outright, / but critics said it would eviscerate the protections / by removing the enforcement powers.','s2 为比喻义，常接 law、argument、institution；字面义为取出屠体内脏。','删除执法权使法律失去效力，体现“抽去实质”义。'],['The amendment eviscerated the protection by strengthening enforcement and giving inspectors new powers.','The amendment strengthened the protection by strengthening enforcement and giving inspectors new powers.','加强执法并赋予新权力是在增强保护，不是抽空保护。'],[[1,'Literally, to eviscerate an animal is to?',['remove its internal organs','cover it with a coat of paint','measure its body temperature'],0,'eviscerate s1 指取出内脏。'],[2,'To eviscerate a law figuratively is to?',['remove its essential force or protections','make it easier to enforce','translate it into another language'],0,'s2 表示抽去法律的实质或效力。'],[2,'Which change might eviscerate an oversight rule?',['removing every power to investigate violations','adding staff and clear enforcement authority','publishing the rule in larger print'],0,'取消调查权限会让监督规定失去实质作用。'],[1,'The word’s Latin element viscera refers to?',['internal organs','river channels','musical sounds'],0,'词源 viscera 指内脏。']]);
P('evocation','由 evoke 加名词后缀 -ation 构成；evoke 源自拉丁语 evocare“召唤出来”，现指唤起记忆、气氛或形象。',[1,'小说写作','The novel’s evocation of a crowded winter market relies on the smell of roasted chestnuts, wet wool, and bus exhaust.','小说通过烤栗子、湿羊毛和公交尾气的气味，唤起了冬日拥挤集市的景象。','The novel’s evocation of a crowded winter market / relies on the smell of roasted chestnuts, wet wool, / and bus exhaust.','不可数名词或可数用法；常与 memory、mood、place 等搭配，指艺术性唤起。','感官细节在读者心中再现市场氛围，体现 evocation。'],['The poem’s evocation erased every memory and made the setting impossible to imagine.','The poem’s obscurity erased every memory and made the setting impossible to imagine.','无法想象环境不是唤起、再现；evocation 应能激活形象或记忆。'],[[1,'An evocation of childhood is?',['a work that brings childhood memories to mind','a device that evaporates water','a tax on locally produced goods'],0,'evocation 指唤起记忆或形象。'],[1,'Which detail may strengthen an evocation of a bakery?',['the smell of warm bread','the legal name of an unrelated company','a random list of numbers'],0,'具体感官细节有助于再现烘焙坊氛围。'],[1,'The noun evocation is related to the verb?',['evoke','evolve','evade'],0,'evocation 由 evoke 派生。'],[1,'Choose the natural phrase.',['an evocation of a vanished city','an evocation to refuse all memory','evocation more evenly'],0,'常见结构是 evocation of + 被唤起的场景或感受。']]);
P('evolution','源自拉丁语 evolvere“展开”，由 e-/ex- 与 volvere“卷”构成；可指生物进化，也可指系统或思想逐渐演变。',[2,'制度发展','The evolution of the lending system took decades: paper cards gave way to barcodes, then to online renewals and shared digital catalogues.','借阅制度的演变历时数十年：纸卡先被条码取代，随后出现在线续借和共享数字目录。','The evolution of the lending system took decades: / paper cards gave way to barcodes, / then to online renewals and shared digital catalogues.','s2 为制度、观念等逐步发展；s1 指生物群体随世代发生变化。','分阶段的技术改变展现制度长期演变。'],['The evolution of the library system happened instantly in one second with no stages or changes over time.','The conversion of the library system happened instantly in one second with no stages or changes over time.','瞬间一次性转换不体现逐步演变过程；conversion 更贴切。'],[[1,'Biological evolution concerns?',['heritable changes in populations across generations','one animal choosing to change its genes overnight','a single fossil being polished'],0,'进化涉及生物群体随世代发生的可遗传变化。'],[2,'The evolution of a language is?',['its gradual development over time','its fixed form that never changes','a device that turns liquid into vapour'],0,'s2 指语言等系统的逐步发展。'],[1,'Which example best illustrates biological evolution?',['a population’s inherited traits shift over many generations','one individual learns to swim','a museum changes its opening hours'],0,'群体性状跨世代变化是生物进化。'],[2,'A historian describes the evolution of an idea. The historian traces?',['how the idea gradually changed','how a species breathes','how a water sample evaporates'],0,'这里关注思想随时间的发展。']]);
P('evolutionary','由 evolution 加 -ary 构成，描述与生物进化或渐进历史变化有关的事物。',[1,'生物学','The evolutionary explanation linked the island birds’ beak differences to food availability across many generations, not to a single season’s weather.','进化论解释把岛上鸟类喙部差异与多代中的食物供应联系起来，而非归因于某一季节的天气。','The evolutionary explanation linked the island birds’ beak differences / to food availability across many generations, / not to a single season’s weather.','形容词，修饰 theory、change、history 等；依语境可指生物或渐变过程。','跨多代的适应变化是进化层面的解释。'],['The evolutionary account claimed that a single bird changed its inherited beak shape completely during one afternoon.','The developmental account described how one bird’s beak grew during its life.','个体一生中的生长是发育变化，不是群体跨世代的进化。'],[[1,'An evolutionary change in a species occurs across?',['generations in a population','one instant in one individual','a single afternoon with no inheritance'],0,'进化变化发生于群体的世代更替中。'],[1,'Which question is evolutionary?',['How did inherited traits in this population change over time?','What colour is one bird’s feather today?','Where is the nearest river mouth?'],0,'进化研究关注群体遗传性状的时间变化。'],[1,'The term evolutionary biology studies?',['biological evolution and its processes','the design of a speech for a memorial','the chemistry of copper etching only'],0,'进化生物学研究生物进化过程。'],[1,'An evolutionary perspective on technology would focus on?',['gradual changes in a system over time','the exact weight of one device only','the name of its manufacturer'],0,'形容词也可用于系统或技术的渐进变化。']]);
P('exacerbate','源自拉丁语 exacerbare“使更粗暴、加剧”，进入英语后主要表示使已存在的问题或症状恶化。',[1,'公共卫生','Using the noisy generator at night would exacerbate residents’ sleep problems, so the clinic moved it farther from the homes.','夜间使用噪音很大的发电机将加重居民的睡眠问题，因此诊所把它移得离住宅更远。','Using the noisy generator at night would exacerbate residents’ sleep problems, / so the clinic moved it / farther from the homes.','及物动词，宾语通常是既有问题、症状或紧张局势；常用 exacerbate a problem。','噪声让原有睡眠问题变严重，符合该动词。'],['The quiet room exacerbated the headache by reducing noise and allowing the patient to rest.','The quiet room alleviated the headache by reducing noise and allowing the patient to rest.','减少噪声并休息会缓解头痛；alleviate 与 exacerbate 意义相反。'],[[1,'To exacerbate a problem is to?',['make an existing problem more severe','solve it completely','describe it without changing it'],0,'exacerbate 表示加重、恶化。'],[1,'Which action could exacerbate a conflict?',['publishing an unverified accusation about one side','holding a fair meeting with both sides','correcting a false rumour promptly'],0,'未经核实的指责可能让冲突加剧。'],[1,'Choose the natural object of exacerbate.',['symptoms','from symptoms','symptomatic'],0,'exacerbate 是及物动词，可直接接 symptoms。'],[1,'The closest opposite of exacerbate is?',['ease','worsen','intensify'],0,'ease 表示缓解，与加剧相反。']]);
P('exacting','由 exact 加 -ing 构成；exact 与拉丁语 exigere“要求、衡量”有关，形容工作要求高、费心力或精确度。',[1,'手工技艺','Restoring the cracked glass was exacting work: each fragment had to be positioned precisely before the adhesive could set.','修复裂开的玻璃十分费心：胶水凝固前必须把每一片碎片准确放好。','Restoring the cracked glass was exacting work: / each fragment had to be positioned precisely / before the adhesive could set.','形容工作、标准或任务要求严格、耗费技巧；不等于单纯“准确的”。','每片玻璃都需精准定位，说明工作 demanding and exacting。'],['The exacting task was effortless and required no care, skill, or attention at any stage.','The simple task was effortless and required no care, skill, or attention at any stage.','无需技巧和投入的任务不具高要求，simple 更符合。'],[[1,'An exacting assignment requires?',['a great deal of effort or precision','no attention or skill','only a change in spelling'],0,'exacting 指需要较多努力、技能或精度。'],[1,'Which job is most likely exacting?',['setting dozens of fragile pieces into a precise mosaic','watching an empty screen for one second','copying a single short word without checking it'],0,'易碎材料的精细拼接对技能和精度要求高。'],[1,'A demanding supervisor may be described as?',['exacting','evanescent','euphonious'],0,'exacting 也可形容要求严格的人。'],[1,'In “an exacting test,” the word means the test is?',['challenging and demanding','already answered','pleasant to hear'],0,'exacting 修饰测试表示要求高、难度大。']]);
P('exaggeration','由 exaggerate 加 -ion；exaggerate 源自拉丁语 exaggerare“堆高、夸大”，名词指夸张行为或夸大说法。',[1,'事实核查','Calling the repair “a total disaster” was an exaggeration: only one small sign had fallen, and no one was hurt.','把维修称为“彻底的灾难”是夸大其词：只掉下来一块小标牌，没有人受伤。','Calling the repair “a total disaster” was an exaggeration: / only one small sign had fallen, / and no one was hurt.','可数名词，可指夸大的言辞；不可数时也可指夸大这一行为。','描述远超实际损害程度，是夸张说法。'],['Her claim that one dropped sign destroyed the entire building was a precise and restrained account with no exaggeration.','Her claim that one dropped sign destroyed the entire building was an exaggeration.','一块标牌却称毁掉整栋楼，显然把事实说得过大。'],[[1,'An exaggeration makes something sound?',['greater or more extreme than it really is','exactly equal to its measured size','impossible to describe'],0,'exaggeration 指把事情说得超过实际程度。'],[1,'Which sentence contains an exaggeration?',['“The queue took forever,” though it lasted ten minutes.','“The queue lasted ten minutes,” with a clock confirming it.','“There were twelve people,” after counting twelve.'],0,'十分钟被说成 forever 是明显夸张。'],[1,'The noun exaggeration comes from which verb?',['exaggerate','examine','evaporate'],0,'exaggeration 是 exaggerate 的名词形式。'],[1,'Choose the opposite of exaggeration.',['understatement','overstatement','hyperbole'],0,'understatement 是轻描淡写，与夸大相反。']]);
P('exalt','源自拉丁语 exaltare“提升、抬高”，由 ex- 与 altus“高”关联；可表示高度赞扬或提升地位。',[2,'历史记述','The monarch exalted the navigator to a new rank after the expedition, granting her the formal title and responsibilities of an admiral.','远征结束后，君主把航海家晋升至新等级，授予她海军上将的正式头衔和职责。','The monarch exalted the navigator to a new rank / after the expedition, / granting her the formal title and responsibilities of an admiral.','s2 为提升至更高地位；s1 表示高度赞扬。','授予更高头衔是提升地位，不只是口头赞美。'],['The review exalted the singer by calling her performance worthless and urging the audience to ignore her.','The review disparaged the singer by calling her performance worthless and urging the audience to ignore her.','贬低而非赞扬，应使用 disparaged。'],[[1,'To exalt a leader in a speech is to?',['praise the leader very highly','reduce the leader’s rank','avoid mentioning the leader'],0,'exalt s1 表示高度赞扬。'],[2,'A ruler may exalt a citizen by?',['raising the person to a higher rank','removing every title and responsibility','writing a private note with no appointment'],0,'exalt s2 可指提升地位或授予更高荣誉。'],[1,'Which verb is closest to exalt in a eulogy?',['glorify','belittle','ignore'],0,'glorify 与高度赞扬接近。'],[2,'The officer was exalted to a higher post. This means the officer was?',['promoted','dismissed','kept entirely outside the service'],0,'to a higher post 表示晋升到更高职位。']]);
P('exasperate','源自拉丁语 exasperare“使粗糙、激怒”，英语中表示把人惹恼到失去耐心。',[1,'日常互动','The repeated software alerts began to exasperate the technician, who had already silenced the same warning three times that morning.','软件警报一再响起，开始令技术员恼火；那天上午他已经把同一警告静音三次。','The repeated software alerts began to exasperate the technician, / who had already silenced the same warning / three times that morning.','及物动词，常用 exasperate someone；描述恼火加深。','警告反复出现使人失去耐心，符合 exasperate。'],['The repeated false alarms exasperated the guard by making him feel calm, patient, and completely unbothered.','The repeated false alarms reassured the guard by making him feel calm, patient, and completely unbothered.','平静且不受困扰是 reassurance，不是激怒。'],[[1,'To exasperate someone is to?',['irritate them greatly','make them feel completely at ease','promote them to a higher rank'],0,'exasperate 表示使恼怒、失去耐心。'],[1,'Which situation might exasperate a commuter?',['the train app gives the same false delay notice every minute','a reliable sign clearly explains the route','a staff member promptly fixes the problem'],0,'反复出现的错误提示容易惹恼乘客。'],[1,'Choose the correct grammatical pattern.',['The delay exasperated us.','The delay exasperated from us.','The delay was an exasperate.'],0,'exasperate 是及物动词，直接接受影响的人。'],[1,'A person who is exasperated is likely to be?',['fed up and irritated','quietly asleep','pleasantly surprised by a gift'],0,'exasperated 描述恼火、受够了的状态。']]);
P('excavation','源自拉丁语 excavare“挖空”，由 ex- 与 cavus“空”构成；指挖掘过程或挖掘形成的坑、工地。',[2,'考古现场','The excavation revealed a stone drain beneath the courtyard, while the team recorded each layer before removing more soil.','挖掘现场在庭院下发现了一条石质排水沟；团队先记录每一层，再继续移土。','The excavation revealed a stone drain beneath the courtyard, / while the team recorded each layer / before removing more soil.','s1 指挖掘过程；s2 可指挖掘形成的地点或坑。','记录土层并移土是考古发掘过程。'],['The excavation was a untouched flat field where no soil had ever been removed.','The grassland was an untouched flat field where no soil had ever been removed.','没有挖动过的平地不是 excavation；grassland 符合原意。'],[[1,'An archaeological excavation is?',['the process of digging to uncover remains','a ceremony praising the dead','the gradual disappearance of a scent'],0,'excavation s1 指考古挖掘过程。'],[2,'“The excavation was fenced off” refers to?',['the hole or site created by digging','a finished written evaluation','a tree species'],0,'excavation s2 可指挖掘现场或挖出的坑。'],[1,'Why record each soil layer during excavation?',['to preserve the context of what is uncovered','to make the site evaporate','to change the name of the river'],0,'层位记录帮助保存遗物的考古背景。'],[2,'A road crew filled the excavation after installing a pipe. What did they fill?',['the trench created by digging','a eulogy','an animal’s cell nucleus'],0,'这里的 excavation 指挖管沟形成的坑道。']]);
P('exceedingly','由 exceed 加副词后缀 -ingly；exceed 源自拉丁语 excedere“越过”，副词可表示极其，也可指过分。',[1,'正式评价','The archive’s catalogue is exceedingly useful to visiting researchers because it links each photograph to its original box and date.','档案馆的目录对来访研究者极其有用，因为每张照片都链接到原始档案盒及日期。','The archive’s catalogue is exceedingly useful to visiting researchers / because it links each photograph / to its original box and date.','s1 为程度很高；s2 表示超过合理限度，需由语境判断。','目录用途很大，exceedingly 加强 useful 的程度。'],['The exceedingly mild breeze was so gentle that it uprooted every tree in the village.','The exceedingly violent storm was so powerful that it uprooted every tree in the village.','连根拔树的强风不可能是 mild breeze；应换成 violent storm。'],[[1,'“Exceedingly rare” means?',['extremely rare','slightly common','not rare at all'],0,'exceedingly s1 表示程度极高。'],[2,'If a fee is exceedingly high, it is?',['more than is reasonable','exactly equal to the average','free of charge'],0,'s2 表示过分地、超出合理程度。'],[1,'Choose the closest paraphrase: “The test was exceedingly difficult.”',['The test was extremely difficult.','The test was almost effortless.','The test was cancelled yesterday.'],0,'此处 exceedingly 相当于 extremely。'],[1,'Which phrase is natural?',['exceedingly carefully prepared','exceedingly a preparation','prepared exceedingly of care'],0,'副词 exceedingly 可修饰 carefully。']]);
P('excellence','源自拉丁语 excellentia“卓越”，与 excellere“高出、胜过”相关，指质量或表现达到很高水准。',[1,'教育','The award recognises excellence in teaching, based on student support, careful lesson design, and evidence that learners make progress.','该奖项依据学生支持、细致的课程设计及学习进步证据，表彰教学卓越。','The award recognises excellence in teaching, / based on student support, careful lesson design, / and evidence that learners make progress.','不可数名词，常用 excellence in + 领域，指高品质或出色表现。','有证据支持的高水平教学符合 excellence。'],['The committee praised the project’s excellence even though it failed every required standard and produced no usable result.','The committee criticised the project’s poor quality because it failed every required standard and produced no usable result.','未达到任何标准不是卓越表现；应描述为质量差。'],[[1,'Excellence in research means?',['a very high standard of quality or performance','an exemption from all rules','a temporary feeling that vanishes'],0,'excellence 指质量或表现的卓越水准。'],[1,'Which achievement shows excellence in craft?',['a precise, durable piece that meets demanding standards','a broken object made without checking','a random pile of unused materials'],0,'精准耐用且达到高标准体现工艺卓越。'],[1,'Choose the natural phrase.',['excellence in service','excellence from service is blue','excellentness of service only'],0,'常用 excellence in + 领域。'],[1,'The opposite of excellence is closest to?',['mediocrity','distinction','superiority'],0,'mediocrity 表示平庸，与卓越相反。']]);
P('exceptionally','由 exceptional 加 -ly 构成；exception 来自拉丁语 exceptio“排除”，副词表示程度或表现超出常态。',[1,'气候记录','The northern station was exceptionally warm in March, with temperatures several degrees above its long-term average for that month.','北部气象站三月异常温暖，气温比该月长期平均值高出好几度。','The northern station was exceptionally warm in March, / with temperatures several degrees above / its long-term average for that month.','副词通常修饰形容词或副词，表示格外、特别；有时也表示特殊情况下。','与长期平均值明显不同，体现程度超常。'],['The station was exceptionally average, matching the long-term norm exactly in every measurement.','The station was completely average, matching the long-term norm exactly in every measurement.','与常态完全一致并不突出；exceptionally 表示超出常态。'],[[1,'“Exceptionally cold” means?',['colder than is usual','exactly the usual temperature','not cold at all'],0,'exceptionally 表示程度格外突出。'],[1,'Which result is exceptionally high?',['a score far above the normal range','a score exactly at the class average','a score that has not been recorded'],0,'显著超过正常范围才称 exceptionally high。'],[1,'Choose the natural placement.',['The material is exceptionally durable.','The exceptionally material is durablely.','The material exceptionally a durable.'],0,'exceptionally 自然修饰形容词 durable。'],[1,'An exceptionally rare bird is?',['much rarer than usual','common everywhere','not a bird'],0,'exceptionally rare 表示格外稀有。']]);
P('exchanger','由 exchange 加施事后缀 -er 构成；工程语境常指在流体之间传递热量或其他量的设备。',[1,'暖通工程','The heat exchanger warmed the incoming water with energy from the outgoing stream, while the two liquids remained in separate pipes.','热交换器利用流出液体的热量加热流入的水，同时两种液体仍在各自管道中流动。','The heat exchanger warmed the incoming water / with energy from the outgoing stream, / while the two liquids remained in separate pipes.','可数名词；工程常见 heat exchanger，设备在介质间传递热量。','两股流体不混合而传热，体现 exchanger 的设备义。'],['The engineer called the insulated storage tank an exchanger even though it transferred no heat or material between fluids.','The engineer called the insulated storage tank a reservoir even though it transferred no heat or material between fluids.','储存而不交换热量的设备是 reservoir，不是 exchanger。'],[[1,'A heat exchanger is designed to?',['transfer heat between fluids','store books on a shelf','remove every atom from a sample'],0,'热交换器在流体间传递热量。'],[1,'In an exchanger, the two fluids may?',['exchange heat while remaining physically separate','always mix into one liquid','both turn into solid metal'],0,'热交换常可发生于彼此隔开的介质。'],[1,'Which phrase is a common technical compound?',['heat exchanger','heat eulogy','heat estuary'],0,'heat exchanger 是常见设备名称。'],[1,'The suffix -er in exchanger names?',['something or someone that exchanges','a past event only','a plural verb tense'],0,'-er 可构成执行交换动作的设备名词。']]);
P('excise','动词 excise 源自拉丁语 excidere“切出”；税收名词则由荷兰语/法语税名进入英语，指特定货物的消费税。',[2,'税务','The excise on locally produced spirits was calculated at the bottling plant, and the company listed the charge separately from sales tax.','本地产烈酒的消费税在装瓶厂核算，公司把这项税费与销售税分开列出。','The excise on locally produced spirits was calculated / at the bottling plant, / and the company listed the charge separately from sales tax.','s2 为税种名词；动词 s1 表示切除组织或删去文字。','对国内生产酒类征收的特定货物税符合 excise 名词义。'],['The surgeon excised the lesion by leaving it untouched and removing healthy tissue around it only.','The surgeon excised the lesion by cutting it out.','excise 的手术义是切除病灶；保留病灶的做法与词义相反。'],[[1,'To excise a paragraph from a draft is to?',['cut or remove it','praise it publicly','divide it into equal shares'],0,'excise s1 表示切除或删去。'],[2,'An excise is a tax typically imposed on?',['particular goods produced or sold in a country','every river at its source','the sound of a spoken sentence'],0,'excise s2 指对特定商品征收的消费税。'],[2,'Which purchase might be subject to an excise tax?',['domestically produced tobacco','a personal memory','a book’s paragraph being edited'],0,'烟草等特定货物可能征收 excise。'],[1,'An editor excised a sentence from the report. The editor?',['removed the sentence','translated it into French','added it twice'],0,'此处 excise 为删除文字。']]);
P('excitable','由 excite 加 -able 构成；excite 源自拉丁语 excitare“唤起、激发”，形容容易兴奋或激动的。',[1,'动物护理','The excitable puppy barked at every passing bicycle, so the trainer practised calm greetings from a distance before moving closer.','这只容易激动的小狗见到每辆自行车经过都会叫，因此训犬师先在远处练习平静打招呼，再逐渐靠近。','The excitable puppy barked at every passing bicycle, / so the trainer practised calm greetings from a distance / before moving closer.','形容人或动物容易被刺激而兴奋、激动或焦躁。','对每辆自行车都强烈反应，表现出易兴奋特征。'],['The excitable puppy remained completely calm during every sudden noise and never reacted to anything.','The unresponsive puppy remained completely calm during every sudden noise and never reacted to anything.','面对刺激毫无反应不符合“容易激动”；unresponsive 更贴切。'],[[1,'An excitable child is one who?',['becomes excited or agitated easily','never reacts to any stimulus','is always asleep'],0,'excitable 表示容易兴奋或激动。'],[1,'Which dog seems excitable?',['one that reacts energetically to every new visitor','one that remains relaxed through every surprise','one that is resting quietly alone'],0,'对每个访客都强烈反应说明容易激动。'],[1,'Excitable describes a tendency to?',['become emotionally aroused quickly','calculate a tax precisely','evaporate a liquid'],0,'该词描述情绪容易被激起的倾向。'],[1,'Choose the closest opposite in this context.',['calm','agitated','high-strung'],0,'calm 与容易激动、躁动相反。']]);

P('excitation','由 excite 加 -ation 构成，excite 源自拉丁语 excitare“唤起、激发”；科学用法指进入较活跃状态的刺激过程。',[1,'神经科学','The brief electrical pulse caused excitation in the nerve cells, producing a measurable signal that travelled along the tissue.','短暂电脉冲使神经细胞受到激发，产生了沿组织传导的可测信号。','The brief electrical pulse caused excitation in the nerve cells, / producing a measurable signal / that travelled along the tissue.','名词，可用于原子、神经或系统；具体含义取决于被激发的对象。','刺激后神经活动增强并产生信号，是 excitation。'],['The pulse caused excitation in the nerve cells by making them less active and eliminating every signal.','The pulse caused inhibition in the nerve cells by making them less active and eliminating every signal.','活动被压低是 inhibition，不是 excitation。'],[[1,'A stimulus causes neural excitation when it?',['increases activity in nerve cells','removes every nerve from the body','turns a cell into a tree'],0,'神经 excitation 指活动受到激发。'],[1,'In a physics experiment, excitation may raise a system to?',['a more active or higher-energy state','a state with no particles at all','a written description of an animal'],0,'科学语境的 excitation 可使系统活跃程度或能量升高。'],[1,'Which event is an example of excitation?',['a light pulse prompts a measurable cellular response','a nerve remains inactive after no stimulus','a river mouth receives a tide'],0,'刺激触发细胞响应体现激发过程。'],[1,'The noun excitation is formed from which verb?',['excite','exclaimation','exhibit'],0,'excitation 是 excite 的派生名词。']]);
P('exciting','由 excite 加 -ing 构成；excite 源自拉丁语 excitare“激发”，形容令人振奋或充满动作、趣味的事物。',[2,'探险','The last stretch of the cave expedition was exciting: a narrow passage opened into a chamber with an underground lake.','洞穴探险的最后一段十分刺激：狭窄通道尽头豁然出现一座地下湖。','The last stretch of the cave expedition was exciting: / a narrow passage opened into a chamber / with an underground lake.','s1 表示使人兴奋；s2 侧重充满动作、趣味或悬念。','通道通向意外发现的地下湖，突出 s2 的刺激与趣味。'],['The exciting expedition was dull and predictable, with no discoveries, movement, or surprises.','The uneventful expedition was dull and predictable, with no discoveries, movement, or surprises.','没有发现与悬念的经历不能称为 exciting。'],[[1,'An exciting opportunity makes people feel?',['eager or thrilled','completely indifferent','physically asleep'],0,'exciting s1 指令人兴奋的。'],[2,'An exciting story is most likely?',['full of interesting action or suspense','a blank page with no events','a tax form with no narrative'],0,'exciting s2 可描述有趣、刺激的内容。'],[1,'Which result would be exciting to a research team?',['a long-sought sample is finally found','the equipment stays switched off','the report is never read'],0,'找到长期寻找的样本通常令人兴奋。'],[2,'Choose the best context for exciting.',['The final chase kept the audience on edge.','The empty stage had no performers or action.','The invoice listed a fixed tax rate.'],0,'追逐使观众紧张投入，体现刺激有趣义。']]);
P('exclusively','由 exclusive 加 -ly 构成；exclusive 源自拉丁语 excludere“排除”，副词表示只限于某人、群体或用途。',[1,'版权许可','The photographs may be used exclusively by the museum until the exhibition closes; other organisations must request permission.','展览结束前，这些照片仅供博物馆使用；其他机构必须申请许可。','The photographs may be used exclusively by the museum / until the exhibition closes; / other organisations must request permission.','副词，修饰动词或介词短语，表示排他地、仅仅属于特定对象。','其他机构须获许可，说明使用权仅限博物馆。'],['The room was reserved exclusively for the choir, so every other group had equal permission to use it.','The room was reserved generally for the choir, so every other group had equal permission to use it.','若所有群体都可同等使用，就不是 exclusively 为合唱团保留。'],[[1,'A service offered exclusively to members is offered?',['only to members','to everyone without restriction','only in the past'],0,'exclusively 表示只限于某群体。'],[1,'Which rule uses exclusively correctly?',['The lab is used exclusively for water testing.','The lab exclusively yesterday a water.','Exclusively lab is used testing water.'],0,'exclusively 自然修饰 used for，说明唯一用途。'],[1,'If a book is sold exclusively online, it is sold?',['only through online channels','in every physical shop','to one named author only'],0,'这里指销售渠道仅限线上。'],[1,'“The fund is exclusively for repairs” means the fund?',['may be used only for repairs','must be used for meals','has no stated purpose'],0,'exclusively for 表示仅用于某目的。']]);
P('excreta','源自拉丁语 excretum“排出的东西”，是 excrete 的复数/集合形式，指身体排出的废物。',[1,'生物学','The field team sealed the animal excreta samples in labelled containers so the laboratory could analyse diet and parasite traces safely.','野外团队把动物排泄物样本封存在带标签的容器中，以便实验室安全分析食性和寄生虫痕迹。','The field team sealed the animal excreta samples / in labelled containers / so the laboratory could analyse diet and parasite traces safely.','通常作不可数或集合名词，涵盖尿液、粪便等排泄废物。','样本用于分析动物排出的身体废物，符合 excreta。'],['The biology report classified clean rainwater collected from a roof as human excreta.','The biology report classified human waste expelled from the body as excreta.','屋顶雨水不是身体排出的废物；excreta 指身体排泄物。'],[[1,'Excreta are?',['waste products expelled from a body','nutrients before they are eaten','a group of musical instruments'],0,'excreta 指机体排出的废物。'],[1,'Which sample is excreta?',['animal faeces collected for analysis','a clean leaf from a tree','water before it enters a pipe'],0,'动物粪便属于排泄物。'],[1,'A study of excreta might examine?',['waste products from digestion and metabolism','the sound quality of a poem','the route of a river to its source'],0,'排泄物研究可分析消化和代谢废物。'],[1,'Excreta is related to which verb?',['excrete','exalt','exaggerate'],0,'excreta 是 excrete 的相关名词形式。']]);
P('excrete','源自拉丁语 excernere“筛出、排出”，由 ex- 与 cernere“分开”构成，指机体排出废物。',[1,'生理学','The kidneys excrete dissolved waste into urine, helping maintain a stable internal balance as blood circulates through the body.','肾脏把溶解的废物排入尿液；血液在体内循环时，这一过程有助于维持内部稳定。','The kidneys excrete dissolved waste into urine, / helping maintain a stable internal balance / as blood circulates through the body.','及物动词；排出者可以是身体、腺体或细胞，宾语多为废物或物质。','肾脏将废物排出到尿液中，符合 excrete。'],['The kidneys excrete waste by retaining every waste product in the blood and releasing none from the body.','The kidneys retain waste by keeping the waste products in the blood rather than releasing them from the body.','保留而不排出是 retain；excrete 表示排泄出去。'],[[1,'To excrete a substance is to?',['discharge it as waste from the body or a cell','absorb it as food','praise it in a speech'],0,'excrete 表示把废物排出。'],[1,'Which organ helps excrete waste from blood?',['the kidneys','the eardrum','the iris'],0,'肾脏过滤血液并排出废物。'],[1,'Choose the correct construction.',['The gland excretes a fluid.','The gland excretes from a fluid.','The gland is an excrete.'],0,'excrete 为及物动词，后直接接排出物。'],[1,'A plant cell may excrete?',['waste products or substances it releases','a eulogy','an estuary'],0,'细胞也可排出代谢废物或其他物质。']]);
P('exculpate','源自拉丁语 exculpare“免除罪责”，由 ex- 与 culpa“过错”构成，表示证明某人无罪或无责。',[1,'调查','The access log exculpated the night guard: her keycard had been used elsewhere when the archive alarm was disabled.','门禁记录证明夜班保安无责：档案室警报被解除时，她的门卡正在别处使用。','The access log exculpated the night guard: / her keycard had been used elsewhere / when the archive alarm was disabled.','正式及物动词，宾语通常是 person；可用 evidence exculpates someone。','门卡记录与指控不符，证据为保安开脱。'],['The video exculpated the driver by clearly showing that he deliberately ran the red light.','The video incriminated the driver by clearly showing that he deliberately ran the red light.','录像显示司机故意闯红灯会使其更受指控，属于 incriminate。'],[[1,'Evidence that exculpates someone?',['clears that person from blame','proves that person committed the act','increases the penalty automatically'],0,'exculpate 表示证明无责、开脱。'],[1,'Which finding might exculpate a suspect?',['a timestamp shows the suspect was elsewhere','a witness identifies the suspect at the scene','the suspect’s fingerprint is on the tool'],0,'案发时不在现场的记录可能证明嫌疑人无责。'],[1,'Choose the correct pattern.',['The records exculpated the clerk.','The records exculpated from the clerk.','The records were an exculpate.'],0,'exculpate 是及物动词，直接接被开脱者。'],[1,'The closest opposite of exculpate is?',['incriminate','absolve','clear'],0,'incriminate 表示使显得有罪，与开脱相反。']]);
P('excusable','由 excuse 加 -able 构成；excuse 经古法语源自拉丁语 excusare“免除责任”，形容情有可原的。',[1,'日常规范','A small delay was excusable because the ferry had stopped for safety during the sudden storm, and the passenger called ahead.','这次小小的迟到情有可原，因为突发风暴中渡船为安全停航，乘客也提前打了电话。','A small delay was excusable / because the ferry had stopped for safety during the sudden storm, / and the passenger called ahead.','形容词，常指错误或失误在当时情境下可以理解、不值得严厉责备。','天气停航且乘客提前通知，解释了迟到原因。'],['The mistake was excusable even though the clerk ignored the clear instructions on purpose and caused preventable harm.','The mistake was inexcusable even though the clerk ignored the clear instructions on purpose and caused preventable harm.','故意无视明确指示并造成可避免伤害，属于不可原谅。'],[[1,'An excusable error is?',['understandable in the circumstances','too serious to forgive in any situation','a planned success'],0,'excusable 表示情有可原、可以理解。'],[1,'Which mistake is most likely excusable?',['a minor typo caused by an unexpected power cut','a deliberate falsification of safety data','repeatedly ignoring a clear warning'],0,'意外断电导致的小错较容易被理解。'],[1,'Choose the natural phrase.',['an excusable delay','an excusable yesterday','excusable to a delay'],0,'excusable 可直接修饰 delay。'],[1,'The closest opposite is?',['inexcusable','understandable','forgivable'],0,'inexcusable 表示不可原谅，与 excusable 相反。']]);
P('execution','由 execute 加 -ion；execute 源自拉丁语 exsequi“完成、执行”，名词可指实施计划，也可指依法处决。',[1,'工程管理','The execution of the bridge repair followed the approved sequence: crews closed one lane, replaced the joint, and tested the surface before reopening it.','桥梁维修按批准的流程实施：施工队先封闭一条车道，更换伸缩缝，再测试路面后重新开放。','The execution of the bridge repair followed the approved sequence: / crews closed one lane, replaced the joint, / and tested the surface before reopening it.','s1 为执行或实施；s2 为依法处死，语境敏感且须明确限定。','按计划完成维修操作体现实施义。'],['The careful execution of the plan meant that no task was performed and the work was abandoned.','The careful cancellation of the plan meant that no task was performed and the work was abandoned.','没有执行而是停止计划，应用 cancellation。'],[[1,'The execution of a plan is?',['the carrying out of its steps','the discussion of an unrelated topic','a type of tree'],0,'execution s1 表示计划的实施。'],[2,'In a legal-history text, execution may mean?',['the carrying out of a lawful death sentence','a routine project meeting','an exemption from tax'],0,'execution s2 指依法处决。'],[1,'Good execution of a repair plan requires?',['doing the approved work in the intended order','writing the plan and never acting on it','changing every step without record'],0,'实施计划就是按安排落实各步骤。'],[2,'A sentence about “the execution was carried out at dawn” most likely concerns?',['a death sentence being carried out','a software feature being evaluated','a river widening into an estuary'],0,'固定表达 carry out an execution 常指执行死刑。']]);
P('exemplary','由 example 经拉丁语 exemplaris“作为范例的”构成；可指值得仿效的，也可指用来警示他人的严厉处罚。',[1,'职业操守','Her exemplary handling of the complaint included a prompt apology, a documented investigation, and a refund without making the customer ask twice.','她处理投诉的方式堪称榜样：迅速道歉、记录调查过程，并主动退款，没有让顾客再三要求。','Her exemplary handling of the complaint included a prompt apology, / a documented investigation, / and a refund without making the customer ask twice.','s1 表示好到值得仿效；s2 可指严厉到足以警戒他人的惩罚。','透明调查、及时道歉与补偿构成值得效法的处理方式。'],['The exemplary response was praised as a model even though it ignored the complaint and refused to investigate.','The exemplary response included a prompt investigation and fair remedy, making it a model for others.','忽略投诉不能作为良好榜样；修正为调查并妥善处理。'],[[1,'Exemplary conduct is conduct that?',['is good enough to serve as a model','should be copied only as a warning','has no example or standard'],0,'exemplary s1 指值得效仿的。'],[2,'An exemplary punishment is intended to?',['deter others through its severity','reward a person for good work','demonstrate a tree’s growth'],0,'s2 指以严厉惩罚警示他人。'],[1,'Which response is exemplary customer service?',['owning an error and correcting it promptly','hiding the error and blaming the customer','deleting the complaint without review'],0,'负责纠错的处理方式可供他人仿效。'],[1,'Choose a close synonym for exemplary in “exemplary leadership.”',['model','shameful','ordinary'],0,'model 表示可作榜样的。']]);
P('exemplification','由 exemplify 加 -ation 构成；exemplify 与拉丁语 exemplum“例子”相关，名词指用具体例子说明一般观点。',[1,'教学写作','The teacher’s exemplification of the grammar rule used two contrasting sentences, allowing students to see how word order changed the meaning.','教师用两个对照句例证语法规则，让学生看出词序变化如何改变含义。','The teacher’s exemplification of the grammar rule used two contrasting sentences, / allowing students to see / how word order changed the meaning.','不可数名词，指以例子说明或展示原则的过程；常与 of 连用。','两个具体句子让抽象规则变清楚，是 exemplification。'],['The paragraph offered no examples or illustrations, so it was a clear exemplification of the rule through examples.','The paragraph offered no examples or illustrations, so it was not an exemplification of the rule through examples.','没有举例就不能称为通过实例说明；加 not 消除矛盾。'],[[1,'Exemplification means?',['showing a general point by giving examples','removing a passage from a law','making a liquid evaporate'],0,'exemplification 指通过实例说明观点。'],[1,'Which paragraph uses exemplification?',['it states a rule and gives two cases that demonstrate it','it lists a title but provides no illustration','it repeats an unrelated date'],0,'列出规则并展示案例是举例说明。'],[1,'Choose the natural construction.',['exemplification of the principle','exemplification from yesterday is blue','exemplification to a principle'],0,'常用 exemplification of + 被例证内容。'],[1,'Exemplification is especially useful when a writer wants to?',['make an abstract idea concrete','hide all supporting cases','describe a person’s birthplace'],0,'例证帮助读者把抽象观点与具体情况联系起来。']]);
P('exemplify','由 example 加动词后缀 -ify 构成；与拉丁语 exemplum“例子”相关，可指作为典型实例或清楚表明。',[1,'文化研究','The town’s shared workshop exemplifies the local tradition of repairing tools together rather than replacing them after a minor fault.','镇上的共享工坊体现了当地一起修理工具、而非小故障就换新的传统。','The town’s shared workshop exemplifies the local tradition / of repairing tools together / rather than replacing them after a minor fault.','s1 为作为典型例子；s2 为清楚显示某种性质或事实。','工坊具体呈现了共同维修的地方传统。'],['The shared workshop exemplified the tradition by refusing to let anyone repair or reuse a tool.','The shared workshop contradicted the tradition by refusing to let anyone repair or reuse a tool.','拒绝修理和再利用与维修传统相反。'],[[1,'A building may exemplify a style if it?',['is a clear, typical example of that style','has no features of the style','was built in another country'],0,'exemplify s1 表示作为典型例证。'],[2,'The data exemplify the problem means the data?',['show the problem clearly','remove the problem from a wall','praise the problem in a speech'],0,'exemplify s2 可表示清楚显示。'],[1,'Choose the correct pattern.',['This case exemplifies the rule.','This case exemplifies of the rule.','This case is an exemplify.'],0,'exemplify 是及物动词，直接接宾语。'],[2,'A calm response may exemplify patience by?',['demonstrating patience in a specific situation','claiming patience but showing anger','measuring a person’s height'],0,'具体行为清楚展现耐心，符合 s2。']]);
P('exemption','源自拉丁语 exemptio“取出、免除”，与 exempt“排除在外”相关，指获准不必遵守规则或缴纳费用。',[1,'税务','The scholarship provides an exemption from tuition fees, but students must still pay for housing and laboratory materials.','奖学金免除了学费，但学生仍需支付住宿费和实验材料费。','The scholarship provides an exemption from tuition fees, / but students must still pay / for housing and laboratory materials.','可数名词，常用 exemption from + 义务、规则或费用。','学生被免除学费这一项费用，体现 exemption。'],['The exemption required every student to pay the fee twice and offered no relief from the rule.','The exemption released eligible students from the fee, though other charges still applied.','要求重复缴费不是免除；修正句明确说明获豁免的费用。'],[[1,'An exemption from a fee means?',['permission not to pay that fee','a requirement to pay it twice','a record of how it was calculated'],0,'exemption 表示获准免缴费用。'],[1,'Which document might grant an exemption?',['a letter excusing a student from one requirement','a bill demanding the full charge','a receipt for a different purchase'],0,'豁免信可准许免除某项要求。'],[1,'Choose the natural phrase.',['an exemption from the rule','an exemption to the rule for paying','an exemption the rule yesterday'],0,'常用 exemption from。'],[1,'Does a tuition exemption necessarily remove housing costs?',['No; it exempts only the stated tuition charge.','Yes; exemption always cancels every expense.','No; it means tuition doubles.'],0,'豁免范围由具体条款限定，不自动涵盖其他费用。']]);
P('exertion','由 exert 加 -ion 构成；exert 源自拉丁语 exertus“伸出、施展”，名词指力气、权力或心力的使用。',[1,'体能训练','After the steep climb, even moderate exertion left the untrained hikers short of breath, so the guide scheduled longer rests.','陡坡攀登后，即使中等程度的体力消耗也让缺乏训练的徒步者气喘吁吁，因此向导安排了更长休息。','After the steep climb, even moderate exertion left the untrained hikers short of breath, / so the guide scheduled / longer rests.','不可数名词，常与 physical、mental、great、without 连用，强调付出的努力或力量。','爬坡使用体力并造成气喘，体现 exertion。'],['The walk required no exertion because the hikers climbed the steep hill while carrying heavy packs without using any effort.','The walk required considerable exertion because the hikers climbed the steep hill while carrying heavy packs.','陡坡加重行李需要大量体力，不是毫不费力。'],[[1,'Physical exertion is?',['the use of bodily effort or strength','a speech praising someone','an exemption from work'],0,'exertion 指力气或努力的使用。'],[1,'Which task requires mental exertion?',['solving a difficult proof','sitting quietly without a task','looking at a blank wall'],0,'复杂证明需要集中思考。'],[1,'Choose the natural collocation.',['great exertion','exertion from yesterday is blue','an exertionly climb'],0,'great exertion 是常见搭配。'],[1,'After prolonged exertion, a person may need?',['rest and recovery','a eulogy','an estuary'],0,'持续用力后通常需要恢复休息。']]);
P('exhalation','由 exhale 加 -ation 构成；exhale 来自拉丁语 exhalare“呼出气息”，名词指呼气或呼出的气体。',[1,'呼吸训练','During exhalation, the singer released air slowly through pursed lips to keep the final note steady.','呼气时，歌手把嘴唇微微收拢，缓慢吐气，以维持最后一个音符平稳。','During exhalation, the singer released air slowly / through pursed lips / to keep the final note steady.','不可数过程名词，也可指一次呼出的气或蒸气；与 inhalation“吸气”相对。','缓慢释放肺内空气是呼气过程。'],['During exhalation, the runner drew fresh air into the lungs for the first time.','During inhalation, the runner drew fresh air into the lungs for the first time.','把空气吸入肺部是 inhalation，不是呼气 exhalation。'],[[1,'Exhalation is the process of?',['breathing air out','breathing air in','holding a written speech'],0,'exhalation 表示呼气。'],[1,'A visible exhalation on a cold day may appear as?',['a cloud of water vapour','a river delta','a copper engraving'],0,'呼出气中的水汽在冷空气中可凝成白雾。'],[1,'Choose the opposite of exhalation.',['inhalation','evaporation','exemption'],0,'inhalation 表示吸气。'],[1,'The singer controlled her exhalation to?',['release air steadily while sustaining a note','raise a tax on goods','remove a paragraph'],0,'控制呼气有助于稳定持续发声。']]);
P('exhaustible','由 exhaust 加 -ible 构成；exhaust 与拉丁语 haurire“汲取、用尽”关联，形容资源可能被耗尽。',[1,'自然资源','Because the aquifer receives little new water, the town treats it as an exhaustible resource and limits pumping during dry years.','由于含水层补水很少，镇上把它视为会枯竭的资源，并在干旱年份限制抽水。','Because the aquifer receives little new water, / the town treats it as an exhaustible resource / and limits pumping during dry years.','形容词，通常修饰 resource、supply 等；表示有尽头、用完后难以补充。','抽取会减少有限的地下水储量，故其可被耗尽。'],['The exhaustible supply could never run out because it was renewed instantly without limit.','The inexhaustible supply could never run out because it was renewed instantly without limit.','永不枯竭应称 inexhaustible；exhaustible 表示会被耗尽。'],[[1,'An exhaustible resource is one that?',['can be used up','cannot ever diminish','is a written example'],0,'exhaustible 表示可以耗尽。'],[1,'Which supply is most clearly exhaustible?',['a finite groundwater reserve with little recharge','an unlimited source replenished instantly','a dictionary definition'],0,'补充很少的有限水储量可能用尽。'],[1,'Choose the natural phrase.',['an exhaustible fuel supply','exhaustible very carefully','an exhaustible yesterday'],0,'exhaustible 可修饰 fuel supply。'],[1,'The closest opposite of exhaustible is?',['inexhaustible','depletable','limited'],0,'inexhaustible 表示不会耗尽。']]);
P('exhaustive','由 exhaust 加 -ive 构成；exhaust 来自拉丁语 haurire“取尽”，形容调查或清单覆盖全面、重要内容无遗漏。',[1,'审计','The auditors completed an exhaustive review of the travel claims, checking every receipt, date, route, and approval before issuing their report.','审计人员对差旅报销进行了全面审查；出具报告前逐一核对每张收据、日期、路线和批准记录。','The auditors completed an exhaustive review of the travel claims, / checking every receipt, date, route, and approval / before issuing their report.','形容词，常修饰 search、review、list、study；表示全面彻底，不是“令人疲惫的”。','各项凭据都被检查，说明审查覆盖全面。'],['The exhaustive search was over in seconds and skipped most rooms, shelves, and storage boxes.','The cursory search was over in seconds and skipped most rooms, shelves, and storage boxes.','快速略过大部分地点是粗略检查，而不是无遗漏的 exhaustive search。'],[[1,'An exhaustive list is?',['so complete that important items are not left out','a short sample chosen at random','a list that contains no entries'],0,'exhaustive 表示全面、无遗漏。'],[1,'An exhaustive search of a building would?',['check all relevant rooms and spaces carefully','look only at the front door','stop before entering the building'],0,'彻底搜查会覆盖所有相关地点。'],[1,'In “an exhaustive report,” exhaustive does not primarily mean?',['tiring the reader physically','covering the subject fully','leaving few important points out'],0,'此义强调内容全面，不是让人疲惫。'],[1,'Choose a common collocation.',['an exhaustive investigation','an exhaustively investigation','an exhaustive to investigate'],0,'exhaustive 可修饰 investigation。']]);
P('exhibitor','由 exhibit 加施事后缀 -or 构成；exhibit 经拉丁语 exhibere“展示”进入英语，指在展会或画廊展出物品的人或机构。',[1,'行业展会','Each exhibitor received one booth at the science fair and was asked to label every device with its maker and a short safety note.','每位参展者在科学展会上分到一个展位，并被要求给每台设备标出制造商和简短安全说明。','Each exhibitor received one booth at the science fair / and was asked to label every device / with its maker and a short safety note.','可数名词，指参加展览并陈列展品的人、团体或公司；与 visitor 区分。','拥有展位并展示设备的单位是 exhibitor。'],['The museum visitor was the exhibitor because she walked through the show without displaying any objects.','The company with a booth displaying its instruments was the exhibitor; the visitor simply attended the show.','只参观而不展出的人是 visitor，不是 exhibitor。'],[[1,'An exhibitor at a trade fair is?',['a person or company displaying products','a visitor who only buys a ticket','a tax on locally made goods'],0,'exhibitor 指在展会上展示物品的一方。'],[1,'Which person is an exhibitor?',['an artist showing paintings in a gallery booth','a guest viewing the paintings','a guard checking the gallery door'],0,'展出作品的艺术家是参展者。'],[1,'The suffix -or in exhibitor helps form a word for?',['a person or organisation that exhibits','the past tense of exhibit','a quality of being even'],0,'-or 在这里构成施事者名词。'],[1,'Choose the natural phrase.',['registered exhibitor','registered exhibitingly','an exhibitor of yesterday only'],0,'registered exhibitor 是自然搭配。']]);
P('exhilarate','源自拉丁语 exhilarare“使欢乐、振奋”，与 hilaris“愉快”相关，表示使人精神振奋、愉悦。',[1,'户外活动','The clear descent on fresh snow exhilarated the skiers, who had waited through several stormy days for safe conditions.','在新雪上顺畅下坡令滑雪者兴奋不已；此前他们为等待安全天气熬过了几天风暴。','The clear descent on fresh snow exhilarated the skiers, / who had waited through several stormy days / for safe conditions.','及物动词，常以人作宾语；描述活跃、畅快的喜悦感。','安全畅快的滑行使滑雪者精神振奋。'],['The long delay exhilarated the passengers by making them frustrated, exhausted, and eager to complain.','The clear announcement reassured the passengers after the long delay and reduced their frustration.','挫败和疲惫不是 exhilarate 带来的振奋感。'],[[1,'To exhilarate someone is to?',['make them feel lively happiness and energy','make them lose every possession','remove a paragraph from a report'],0,'exhilarate 表示使人振奋愉快。'],[1,'Which event might exhilarate a young pilot?',['a smooth first solo flight','a cancelled flight with no explanation','a long wait in a locked room'],0,'成功首次单飞可能令人振奋。'],[1,'Choose the grammatical sentence.',['The mountain air exhilarated us.','The mountain air exhilarated from us.','The mountain air was an exhilarate.'],0,'exhilarate 是及物动词，直接接宾语。'],[1,'The closest meaning of exhilarate is?',['invigorate','exasperate','exhaust'],0,'invigorate 表示使精神焕发，与之接近。']]);
P('exhilarating','由 exhilarate 加 -ing 构成，形容能带来畅快愉悦和活力的事物。',[1,'运动体验','The exhilarating descent gave the cyclists a burst of energy, although they slowed down before the sharp bend at the bottom.','畅快的下坡让骑行者精神一振，不过他们在底部急弯前减慢了速度。','The exhilarating descent gave the cyclists a burst of energy, / although they slowed down / before the sharp bend at the bottom.','-ing 形容词描述事物带来的效果；常形容运动、经历或消息。','下坡带来活力和愉悦感，符合 exhilarating。'],['The exhilarating ride was tedious and left every passenger bored and half asleep.','The tedious ride was dull and left every passenger bored and half asleep.','令乘客厌倦欲睡的旅程不是 exhilarating。'],[[1,'An exhilarating experience makes a person feel?',['cheerful, energised, and stimulated','completely bored and sleepy','unable to understand a word'],0,'exhilarating 指令人振奋、畅快。'],[1,'Which activity sounds exhilarating?',['a challenging flight over a mountain ridge','waiting in a silent queue with nothing to do','reading an empty page'],0,'有挑战且充满活力的飞行可能令人振奋。'],[1,'Choose the natural phrase.',['an exhilarating performance','an exhilarated performance causes joy','an exhilaratingly performance'],0,'形容带来感受的事物用 exhilarating performance。'],[1,'An exhilarating match is likely to leave fans?',['energised and excited','indifferent because nothing happened','asleep before it begins'],0,'振奋的比赛会使观众兴奋投入。']]);
P('exhilaration','由 exhilarate 加名词后缀 -ation 构成，源自拉丁语 exhilarare“使愉快”，指活跃而振奋的喜悦感。',[1,'个人体验','A sudden burst of exhilaration swept through the crew when the lighthouse beam appeared, confirming that they had reached the coast safely.','灯塔光束出现、确认船员已安全抵岸时，一阵振奋的喜悦涌上大家心头。','A sudden burst of exhilaration swept through the crew / when the lighthouse beam appeared, / confirming that they had reached the coast safely.','不可数情绪名词，指活跃的愉悦和兴奋；与 calm relief 有联系但更振奋。','安全抵岸带来的欣喜与活力体现 exhilaration。'],['The crew felt exhilaration when they learned that the voyage had failed and everyone was stranded without supplies.','The crew felt despair when they learned that the voyage had failed and everyone was stranded without supplies.','航行失败且被困无补给通常带来绝望，不是振奋喜悦。'],[[1,'Exhilaration is a feeling of?',['lively joy and excitement','deep boredom and indifference','physical exhaustion only'],0,'exhilaration 指活跃的喜悦与兴奋。'],[1,'Which moment might bring exhilaration?',['hearing that a difficult rescue succeeded','being told a planned event was cancelled','watching a blank screen for hours'],0,'艰难救援成功会带来振奋和喜悦。'],[1,'The noun exhilaration is related to which verb?',['exhilarate','excavate','exculpate'],0,'exhilaration 由 exhilarate 派生。'],[1,'Choose the closest synonym.',['elation','despair','fatigue'],0,'elation 表示兴高采烈，与 exhilaration 接近。']]);

})();
